SY_TALK("OzuVgRK61mg.hi",[[0,["और ये शक्ति जिसके भक्त हुए हैं, ये","शक्ति हमारे भीतर में है ।"]],[8,["इसको समझना चाहिए, कि जिस चीज़ की हम","इतनी वर्षों से भक्ति करते आये हैं, शायद वो","हमारे भीतर में हो सकती है।"]],[20,["और तभी, उसकी हम भक्ति करते हैं, कि","काश एक दिन हम उसे पहचान पाएँ।"]],[28,["ये जो शक्ति है हमारे भीतर में, इसको","कुण्डलिनी कहते हैं।"]],[35,["और जो तीन शक्तियें हैं - महाकाली,","महासरस्वती और महालक्ष्मी"]],[43,["उन्हीं तीन शक्तियों का ये एक प्रतिबिम्ब है,","जो कि ईश्वर के द्वारा ईश्वर की इच्छा की","शक्ति है।"]],[54,["और ये जो चार्ट है हमारे भीतर, इस चार्ट में","दिखाया गया है, कि जो सुषुम्ना नाड़ी है,","जो रीढ़ की हड्डी है"]],[64,["उसका जो अंतिम स्थान है, वहाँ ये कुण्डलिनी","की जो शक्ति है, वहाँ ये ठहरी हुई है।"]],[74,["अब ये शक्ति हमारे भीतर जब जागरुक हो","जाती है, तभी, हमारी आत्मा में प्रकाश आता है।"]],[87,["और उस आत्मा के द्वारा हमारी चेतना बढ़ती","है। जब तक कि हमारे सहस्त्रार पे,"]],[98,["हमारा जो मस्तिक्ष है, उसमें उसका पूरी तरह","प्रकाश नहीं होता है।"]],[106,["जब उसका पूरी तरह प्रकाश हो जाता है, तो","उस स्थिति को मोक्ष कहा जाता है।"]],[113,["इसी मोक्ष से हम ईश्वर को पा लेते हैं। पर","ये मोक्ष इस तरह नहीं है कि हमें"]],[122,["घर बार छोड़ना होगा या हमें सन्यासी","बनना होगा।"]],[127,["सहज योग के अनुसार, हमें गृहस्थ में ही रहकर,","दुनियादारी में ही रहकर, ये स्थिति पानी होगी।"]],[139,["तो किस तरह ये होता है, यही सहज योग","का विषय है।"]],[144,["आप देख रहे हैं कि आपके सामने एक चार्ट है,","और उस चार्ट में तीन नाड़ियाँ दिखाई गईं हैं।"]],[152,["ये तीन नाड़ियाँ हैं। जो इस साइड की है, ये हमारी","इच्छा शक्ति है, जो कि महाकाली की शक्ति है।"]],[163,["जो दूसरी साइड में है, ये है महासरस्वती की","शक्ति जो हमारी क्रिया शक्ति है।"]],[173,["तो इच्छा शक्ति और क्रिया शक्ति जब बैलेंस","में होते हैं, जब बराबर होते हैं,"]],[181,["तभी ये जो सुषुम्ना नाड़ी है, इसके द्वारा","ये कुंडलिनी चढ़ती है।"]],[187,["और इसके ही चढ़ने से, बहुत से रोग हमारे भीतर","जो हैं, वो दूर हो जाते हैं और उसी से हमें आत्मा","के प्रकाश होने से शांति मिलती है।"]],[201,["ये शांति इस तरह नहीं है कि एक मंत्र का जाप","करते जाइए, करते जाइए, तो उसमें आदमी","कुछ देर में स्थिर हो जाता है -"]],[209,["वो स्थिरता में चेतना नहीं होती, पर इस ध्यान","के मार्ग से, आदमी निर्विचार चेतना में होता है -"]],[219,["कि चेतना भी होती है और निर्विचार भी होता","है। तो दोनों चीज़ें जो हैं, वो अवश्य हैं।"]],[226,["उसी से हमें आत्मसाक्षात होता है।"]],[230,["तो अब इसके विषय में बहुत सी चीज़ें हैं,","पर जो मुख्य चीज़ है, वो ये है, कि किस तरह","इसका जागरण किया जाए।"]],[241,["जैसे हम कहते हैं, कि देवी का जागरण है या","देवी की भक्ति की जाती है इसलिए कि ये","जागरूक हों,"]],[251,["तो कौन इसे जागरूक कर पायेगा? इसे जागरूक","करने के लिए केवल वो शक्ति खुद ही जागरूक","कर सकती है।"]],[259,["और वो ही शक्ति आज इस संसार में आयीं हैं,","जो कि श्री माताजी निर्मला देवी हैं।"]],[268,["इनके बारे में बहुत कुछ लिखा गया है और","बहुत से वर्षों पहले, १४००० पहले, जो कि","ऋषि हुए भुजंदर नाम के"]],[283,["उन्होंने कहा था कि, इस युग में एक मन्वन्तर","आएगा, जिसमें ये शक्ति होगी कि दूसरों की","शक्ति भी उठाएगा।"]],[292,["इनके बारे में भृगु समिति में भी लिखा गया है।","और अमेरिका में एक बहुत प्रसिद्ध दूरदर्शी हुए,"]],[302,["जीन डिक्सन, जिन्होंने भी इनके बारे में कहा","गया है। और हम लोग भी इन्हें इसी तरह","पहचान पाते हैं,"]],[309,["कि इनके द्वारा एक चैतन्य लहरी बहती है।","और इस चैतन्य से जो भी हमारे भीतर में रोग","होते हैं,"]],[323,["जो भी हमारे चक्र बिगड़े होते हैं, वहाँ पर इनका","अगर हम चैतन्य दें, तो वो चक्र भी ठीक हो जाते","हैं और वो रोग भी ठीक हो जाते हैं।"]],[333,["इस तरह सारे संसार में, जगह-जगह में,","लोगों ने इसका अनुभव किया है।"]],[340,["और उस अनुभव के सबूत से ये साबित होता है,","कि ये शक्ति हैं, कि इनकी दी हुई इस भेंट से,"]],[353,["सहज योग से, बहुत से लोग पार हो गए हैं और","यही हमने आज पाना है। इसीलिए हम यहाँ","आये हैं।"]],[362,["आज श्री माताजी निर्मला देवी जी, जयपुर आईं","हैं और कुछ ही समय में यहाँ बिराजेंगीं।"]],[371,["उस देर में, हमारे भीतर में, एक ऑस्ट्रेलिया से","डॉक्टर साहब आएं हैं, जिन्होंने बहुत सी","बीमारियों का रिसर्च किया है"]],[383,["और उन्होंने बहुत सी बीमारी इस सहज योग","के द्वारा, इनके चैतन्य के द्वारा, बहुत सी","बीमारियाँ ठीक कर दीं हैं।"]],[393,["और अब इस विषय में वो आपको बताएँगे, कि","किस तरह कई बीमारियाँ ठीक हो जा सकतीं हैं"]],[401,["जो कि एक साईकोसोमैटिक हैं, या जिसे कह","लीजिए मानसिक हैं, और किस तरह हम अपनी","साधना करेंगे,"]],[415,["किस तरह हम अपने जीवन में सहज लाएँगे,","जिससे ये सहज योग, ये कुण्डलिनी की शक्ति,","हमारे भीतर जागरूक हो और स्थिर हो।"]],[426,["तो अभी हम डॉक्टर वारेन साहब को बुलाते हैं,","जो कि आपको ये समझाएँगे।"]],[434,["सहज योगी: डॉक्टर वॉरेन, मैंने अभी इनसे","कहा है, कि आप उन्हें समझाएँगे,"]],[438,["कि विभिन्न मनोदैहिक बीमारियाँ सहज योग से","कैसे संबंधित हैं और वे कैसे ठीक होती हैं।","डॉक्टर वॉरेन"]],[452,["डॉक्टर वॉरेन: जयपुर के लोगों को सुप्रभात।","यह एक ऐसे डॉक्टर के लिए संतुष्टिदायक है"]],[460,["जो चिकित्सा के बारे में अपने संकीर्ण दृष्टिकोण","में बहुत अधिक लिप्त/ग्रस्त है,"]],[465,["अपने संकीर्ण विचारों में, कि हम मानव","बीमारी का इलाज कैसे करते हैं।"]],[470,["इस निष्कर्ष पर पहुँचना, कि तथाकथित बीमारी","के सभी कारण सूक्ष्म प्रणाली के भीतर हैं,"]],[478,["और उस सूक्ष्म प्रणाली को समझाया जा सकता है,","कि सूक्ष्म प्रणाली को क्रियान्वित किया जा","सकता है,"]],[484,["और वह सूक्ष्म प्रणाली सभी बीमारियों","को ठीक कर सकती है।"]],[490,["योगीजी ने कहा कि हम मनोदैहिक बीमारी को","देख रहे हैं। साइको - बायीं ओर की बीमारियाँ हैं,"]],[500,["बीमारियाँ, यदि आप चाहें, तो हमारे उस हिस्से","से जुड़ी, भावनाओं से जुड़ी हैं, जो मनस शक्ति","है।"]],[508,["दैहिक का अर्थ है, देह का, शरीर का और इसलिए","यह शब्द का अर्थ है, जैसा कि हम इसे कहते हैं,"]],[515,["(भौतिक) शारीरिक स्वास्थ की बीमारी","और वह दाहिना पक्ष है।"]],[520,["इसका संबंध हमारे अस्तित्व के दो पक्षों से है,","जिन्हें आप लोग युगों-युगों से इड़ा नाड़ी और","पिंगला नाड़ी के रूप में जानते हैं।"]],[530,["वे दो नाड़ियाँ युगों-युगों से हमारे जीवन की","कार्यप्रणाली रही हैं।"]],[538,["हम किसी न किसी के चरम में जी रहे हैं और","धीरे-धीरे अपनी खोज में हम उस बिंदु पर"]],[544,["आ गए हैं, जहाँ हम सुषुम्ना नाड़ी के माध्यम से","अपने आरोहण (उत्थान) के लिए तैयार हैं।"]],[549,["केंद्रीय चैनल के माध्यम से, अपने उत्थान के","लिए तैयार हैं। तो जो कुछ भी होना है वह यह है,"]],[556,["कि किसी चीज़ को इसे ट्रिगर करना होगा।","वह कुछ ऐसा है, जो श्री माताजी आप में से"]],[562,["प्रत्येक के लिए करने में सक्षम हैं, और फिर आप","दूसरों के लिए करने में सक्षम होते हैं।"]],[565,["लेकिन बीमारी का कारण क्या है? ऐसा इसलिए","है, क्योंकि हम इन चक्रों के किसी न किसी चरम,","किसी न किसी स्तर पर रह रहे हैं।"]],[576,["चक्र कारण है, नाड़ियों का अवरुद्ध होना कारण","है, बायीं ओर, दायीं ओर का असंतुलन,","सभी रोगों का कारण है।"]],[586,["मुझे मधुमेह सिर्फ इसलिए नहीं होता क्योंकि","मैं चीनी खाता हूँ। वास्तव में इसका चीनी से","बहुत कम लेना-देना है।"]],[592,["मैं किसी ऐसे व्यक्ति की वजह से नर्वस","ब्रेकडाउन का शिकार नहीं हो जाता जो हमें","परेशान करने की कोशिश कर रहा है।"]],[602,["जब तक सूक्ष्म शरीर में कोई कारण न हो,","मुझे गंभीर मांसपेशीय विकृति या कोई","असाध्य रोग नहीं होता।"]],[612,["इसलिए, हम डॉक्टरों को, कम से कम, कारणों","की भूमिका पर ध्यान देना चाहिए, कम से कम।"]],[619,["वास्तव में हम जो कर रहे हैं, वह मुख्य रूप से,","प्रभावों की भूमिका पर ध्यान दे रहे हैं। प्रभाव","रोग है, कारण चक्र के भीतर है।"]],[629,["लेकिन वास्तविक इलाज कारण से परे है।","इलाज कुंडलिनी के उत्थान और चक्र की","मरम्मत (सुधार) में है,"]],[639,["क्षति को बेअसर करने और चक्रों और नाड़ियों में","बाधाओं और रुकावटों को दूर करने में है, जैसा","कि आप जानते हैं।"]],[649,["अतः सूक्ष्म शरीर और स्थूल शरीर के","बीच सीधा सम्बन्ध है।"]],[657,["यदि हमारे भीतर, उदाहरण के लिए, यह विशुद्धि","चक्र है, तो इस बिंदु पर, यह विशुद्धि चक्र सीधे","ग्रीवा जाल से संबंधित है।"]],[669,["सर्वाइकल प्लेक्सस(ग्रीवा जाल) में सोलह","सबप्लेक्सस होते हैं"]],[675,["जो हमारे शरीर के इस क्षेत्र में हमारी शारीरिक","प्रणालियों की सभी अभिव्यक्तियाँ देते हैं।"]],[682,["यह बालों को भी नियंत्रित करता है, यह हमारी","आंख के बाहरी हिस्सों को नियंत्रित करता है,"]],[690,["यह हमारी सुनने की क्षमता को नियंत्रित करता","है, यह चेहरे, नाक और इन सभी क्षेत्रों की","मांसपेशियों को नियंत्रित करता है।"]],[696,["यह थायरॉयड ग्रंथि और पैराथायराइड ग्रंथि","को नियंत्रित करता है।"]],[699,["यह गर्दन की सभी मांसपेशियों को नियंत्रित","करता है। यह हमारे उस हिस्से को भी नियंत्रित","करता है, जो बहुत तनावग्रस्त"]],[706,["और बहुत तंग हो जाता है, जब हम जीवन के","नाटक को देखने में असमर्थ हो जाते हैं।"]],[711,["और इसलिए, इसमें कोई आश्चर्य की बात नहीं","है, कि जो देवता इस चक्र को नियंत्रित करते हैं,"]],[717,["वे कोई और नहीं, बल्कि स्वयं साक्षी, भगवान","कृष्ण हैं, जिन्होंने वैराग्य(साक्षी भाव) का गुण","प्रकट किया है।"]],[725,["इसलिए, जब कुंडलिनी इस बिंदु तक बढ़","जाती है, तो वह इस केंद्र पर होने वाली"]],[733,["किसी भी रुकावट को पूरी तरह से बेअसर कर","देती है और फिर इस स्थान का विस्तार","करना शुरू कर देती है,"]],[740,["ताकि भगवान कृष्ण और उनकी शक्ति राधा,","की गुणवत्ता उस स्तर पर खुद को व्यक्त","करना शुरू कर दे।"]],[748,["और इस प्रकार गीता का संदेश आपके भीतर","प्रकट होना शुरू हो जाता है।"]],[754,["आप भगवान कृष्ण के गुण बन जाते हैं, आप","वह सब कुछ बन जाते हैं जो गीता है।"]],[760,["गीता स्वयं प्रबुद्ध हो जाती है क्योंकि आप साक्षी","बन जाते हैं, आप अनासक्त व्यक्ति बन जाते हैं,","आप वह बन जाते हैं, जो ज्ञान है।"]],[774,["आप जानते हैं, कि यदि आप एक","आत्मसाक्षात्कारी नहीं हैं, तो श्री कृष्ण","आपसे बात कर रहे हैं।"]],[780,["यदि आप एक आत्मसाक्षात्कारी हैं, तो कृष्ण","आपसे दूसरे स्तर पर बात कर रहे हैं।"]],[784,["और इस प्रकार, हम भगवद गीता में व्यक्त की","गई दिव्य लीला के विभिन्न स्तरों को","समझना शुरू करते हैं।"]],[793,["ये सभी बातें उजागर होने लगती हैं","लेकिन बहुत ही सांसारिक स्तर पर।"]],[797,["व्यावहारिक स्तर पर इस केंद्र में आने वाली","सभी बीमारियाँ ठीक हो जाती हैं।"]],[803,["उदाहरण के लिए, यदि हमारे पास थायरॉयड","की समस्या से पीड़ित रोगी है,"]],[808,["तो इसका कारण यह है कि विशुद्धि चक्र के","दाहिने हिस्से में कुछ असंतुलन है।"]],[813,["यदि हमारे शरीर में कैल्शियम और फास्फोरस","के असंतुलन की कोई समस्या है,"]],[818,["तो इसका संबंध चक्र के बाईं ओर से है, जो","पैराथाइरॉइड ग्रंथि को नियंत्रित करता है।"]],[824,["यदि हमें स्पोंडिलोसिस हो गया है, जो विशुद्ध रूप","से इस स्तर की कशेरुक संरचनाओं की","एक अपक्षयी स्थिति है,"]],[833,["और यह एक्सरे पर दिखाई देता है और आपमें","से अधिकांश में/पर इसका कुछ असर है - बहुत","से भारतीय लोग इस समस्या से पीड़ित हैं"]],[840,["ऐसा इसलिए है क्योंकि यह चक्र संकट में है।","यदि आपको हृदय की कुछ समस्याएं हैं,"]],[847,["यदि आपको एंजाइनस पेक्टोरिस है, आपको","सांस फूलने की समस्या है और बाएं हाथ","में दर्द हो रहा है,"]],[854,["सीने में दर्द के बिना सीढ़ियां चढ़ने में असमर्थता","है, तो यह भी इस विशुद्धि चक्र से संबंधित है,","साथ में हृदय चक्र के साथ."]],[863,["इसलिए आप चीजों को इस आधार पर देखना","शुरू कर सकते हैं, कि चक्र किस प्रकार कार्य","कर रहा है"]],[869,["और यदि यह ठीक से कार्य नहीं कर रहा है, तो","रोग प्रक्रिया, अंततः, स्वयं ही प्रारंभ हो जाएगी।"]],[876,["यदि यह पहले से ही प्रारंभ नहीं हुई है, तो यह","प्रारंभ हो जाएगी, क्योंकि जो सूक्ष्म में है, अंततः","उसे स्थूल में व्यक्त होना ही पड़ता है।"]],[886,["तो, हम सहज योग में क्या हासिल करते हैं?","जब कुंडलिनी केंद्रीय चैनल के माध्यम","से ऊपर उठती है,"]],[892,["तो यह उस चक्र को पोषण देना शुरू कर देती है,","जो संकुचित या क्षतिग्रस्त हो गया है"]],[899,["या यहाँ तक कि, उदाहरण के लिए, कैंसर","के मामले में, एक टुकड़ा टूट गया है/","पूरे से अलग हो गया है।"]],[903,["चक्र का एक टुकड़ा वस्तुतः स्वयं को","संपूर्ण से अलग कर लेता है"]],[907,["और तेजी से ऊपर उठता हुआ अपने आप","(अपनी मर्ज़ी से) कार्य करने लगता है।"]],[913,["जो कुछ भी है, यह कुंडलिनी उस बिंदु तक उठते","हुए, केंद्र को ऊर्जा प्रदान करना शुरू कर देती है,","जो इसे वापस संतुलन में लाती है।"]],[924,["एक मामले को बिंदुवार लीजिए। यदि हम चरम","स्थितियों में जी रहे हैं, उदाहरण के लिए,"]],[928,["यदि हम लगातार दूसरे व्यक्ति पर हावी हो रहे","हैं, यदि हम दूसरों पर हावी होने के लिए अपनी","आवाज का उपयोग कर रहे हैं,"]],[935,["विशेष रूप से इस चक्र से आ रही है, तो हमें","थायराइड की समस्या हो सकती है।"]],[941,["हम में थायराइड विकसित हो सकता है, जो या","तो अति सक्रिय या कम सक्रिय है।"]],[948,["डॉक्टर इसका इलाज करेंगे, हम इसके लिए","कुछ चिकित्सा या प्राकृतिक उपचार देंगे"]],[954,["लेकिन हम केवल कारण का इलाज कर रहे हैं","और अंततः, यदि वह व्यक्ति अपने","आक्रामक शब्दों"]],[959,["और अपने तरीके के माध्यम से, अपने","जीवन में दूसरों पर हावी होने की,"]],[961,["एक हावी व्यक्ति बनने की प्रवृत्ति को नहीं","बदलता है, डॉक्टर को कुछ हासिल नहीं","होने वाला।"]],[972,["जो होना है वह यह है, कि अस्तित्व का आंतरिक","परिवर्तन होना चाहिए।"]],[977,["इस स्तर पर, दिव्य गुण की अभिव्यक्ति होनी","चाहिए, जो संभावित रूप में आपके भीतर","निर्मित हुई है,"]],[987,["जिसे आत्म-साक्षात्कार के बाद, दिव्य गुण के","रूप में विस्तारित किया जा सकता है।"]],[993,["यह कुंडलिनी जागरण का कार्य है, इस अर्थ में","कि यह उन सभी समस्याओं को बेअसर"]],[1003,["कर देता है, जिनका हमें चिकित्सा विज्ञान","में सामना करना पड़ता है।"]],[1006,["इसलिए बजाय इसके कि हम कहें, \"मुझे","एक बेहतर इंसान बनना है, मुझे कम","आक्रामक होना है,"]],[1012,["मुझे लोगों से बात करने के तरीके में और","अधिक मधुर होना है,\" बजाय इसके कि","हम इसे उस तरीके से करें,"]],[1019,["जो विफल हो गया है, स्पष्ट रूप से यह विफल","हो गया है, होता यह है कि, कुंडलिनी सहज","तरीके से"]],[1027,["और अपनी सहज बुद्धि के साथ ऊपर उठती है,","यह जानती है कि किस चक्र को पोषित करना है,"]],[1034,["यह जानती है कि उस केंद्र में कितनी ऊर्जा","छोड़नी है, यह जानती है कि चक्र की किस","पंखुड़ी पर अपना ध्यान केंद्रित करना है,"]],[1045,["ऊर्जा बढ़ती है और धीरे-धीरे रुकावट खत्म","हो जाती है और सामान्य स्वास्थ्य बहाल","हो जाता है।"]],[1051,["मेरे मामले को (बिंदु पर) ले लो। जब मैं सहज","योग में आया तो मुझे दो दिल के दौरे, दो हृदय","रोधगलन हो चुके थे।"]],[1060,["मुझे हेमी पैरालिसिस था, जो कम से कम पूरे","शरीर के एक तरफ की मांसपेशियों की","कमजोरी है,"]],[1067,["इसलिए एक तरफ, कुछ हद तक, लकवा","मार गया था।"]],[1072,["मुझे लीवर की गंभीर समस्या थी, मुझे माइग्रेन","का सिरदर्द था और साइटिका की बीमारी थी।"]],[1078,["इसलिए मेरे पास चिकित्सा विज्ञान के","संदर्भ में एक पूरी किताब थी।"]],[1084,["लेकिन इसके बावजूद, मुझे पता था कि जब मुझे","आत्म-साक्षात्कार प्राप्त हुआ, तो यही","सच्चाई थी।"]],[1091,["मुझे अचेतन, चैतन्य के स्पंदन महसूस होने","लगे। मैंने अपनी उंगलियों पर"]],[1099,["भगवान की सर्वव्यापी शक्ति को महसूस","करना शुरू कर दिया,"]],[1101,["जिसे आप हिंदू लोग ब्रह्मशक्ति, चैतन्य के रूप","में जानते हैं - आप इन चीजों को जानते हैं।"]],[1111,["मैंने इसे महसूस करना शुरू कर दिया और जब","मैंने इसे महसूस किया, तो मुझे अपने अंदर एक","शांति महसूस हुई - यह पहली बात थी।"]],[1117,["मुझे श्री माताजी के बारे में एक मान्यता महसूस","हुई, कि वह मानवता की पीड़ा का समाधान है।"]],[1126,["मैंने इसे महसूस किया क्योंकि तार्किक रूप से मैं","अपने तर्कसंगत मस्तिष्क के साथ उस निष्कर्ष","पर पहुँचा था।"]],[1133,["यदि ईसाई परंपरा में भगवान कृष्ण के समय","तक एक पिता, ईश्वर पिता थे, तो भगवान","यीशु मसीह के रूप में"]],[1142,["तो भगवान यीशु मसीह के रूप में एक पुत्र","महाविष्णु भी थे, तो तार्किक रूप से,"]],[1147,["एक माँ भी होनी चाहिए थीं हमें","आत्मसाक्षात्कारी आत्माओं के रूप में","जन्म देने के लिए।"]],[1153,["कोई तो होना चाहिए जो हमें जागरूकता के","अगले चरण में ले जाए, जो हमें मानवीय","सीमाओं के साथ,"]],[1159,["इस मानवीय स्थिति से बाहर निकालकर","जागरूकता के अगले चरण में ले जाए,","जो आध्यात्मिक है।"]],[1170,["यही कारण है कि हम यहाँ हैं, हम साधक हैं, हम","उस अगले उत्क्रांतिक कदम की तलाश कर रहे हैं"]],[1177,["और जब हम वह अगला उत्क्रांतिक कदम","उठाते हैं, तो हम ईश्वर के राज्य में प्रवेश करते हैं"]],[1182,["और हम सर्वशक्तिमान ईश्वर के साथ उस","अंतिम पुनर्मिलन की प्रक्रिया शुरू करते हैं,","जिसकी हम युगों-युगों से तलाश कर रहे हैं।"]],[1193,["हम हिंदू हो चुके, हम मुसलमान हो चुके,","हम ईसाई हो चुके, हम यहूदी हो चुके,"]],[1198,["हमने उन महान अवतारों की शिक्षाओं को किया","और जाना है। हमने सार को हमारे भीतर","आत्मसात कर लिया है,"]],[1206,["और हमारे भीतर मस्तिष्क की कोशिकाएं हमारी दिव्य प्रकृति के अधिक अनुभव के लिए प्यासी हो गई हैं"]],[1216,["और इसलिए साधक स्वरुप जब हम सत्य से","मिलते हैं, जब यह आत्मा परमात्मा को छू","लेती है,"]],[1223,["जब यह शिव सदाशिव बन जाते हैं, जब आप","उन सभी चीजों का अनुभव करना शुरू कर","देते हैं"]],[1230,["जिनकी हम सभी तलाश कर रहे हैं, तो भगवान","की शांति आप पर उतरना शुरू हो जाती है।"]],[1235,["ब्रह्मशक्ति नीचे उतरने लगती है और आप","इसे हाथ पर ठंडी हवा के रूप में महसूस","करने लगते हैं।"]],[1241,["आप अपनी उंगलियों पर विभिन्न चक्रों की","अभिव्यक्ति महसूस करना शुरू करते हैं -"]],[1247,["प्रत्येक उंगली एक अलग चक्र से संबंधित होती","है। यह उंगली हृदय है, यह उंगली आज्ञा चक्र है,"]],[1254,["यह उंगली मणिपुर चक्र है, यह विशुद्धि है, यह","स्वाधिष्ठान है, यह मूलाधार है और हथेली के","ठीक मध्य में सहस्त्रार है -"]],[1266,["हजार पंखुड़ियों वाला कमल, अंतिम चक्र, वह","चक्र जो अब हमारी जागरूकता में खुल रहा है।"]],[1274,["आप इसे अपनी उंगली के पोरों पर महसूस","करते हैं और आप इसका अनुभव करना","शुरू कर देते हैं।"]],[1278,["अब आपको विद्या को जानना है, समझना है","और इसीलिए हम यह कार्यशाला कर रहे हैं,"]],[1284,["ताकि आप विद्या के बारे में और अधिक","जान सकें।"]],[1287,["श्री माताजी आ चुकी हैं और वह आपको इस बारे","में और अधिक बतायेंगीं जितना मैं कभी उम्मीद","स्वयं से कर सकता हूँ।"]],[1300,["श्री माताजी: बैठिए, बैठिए आप। आप लोग","पधारिए, आप लोग पधारिए, पधारिए।"]],[1323,["अब पधारिए।"]],[1325,["डॉक्टर वॉरेन: सूक्ष्म और स्थूल के बीच","संबंध के कुछ उदाहरण"]],[1329,["सहज योगी: श्री माताजी के बारे में आपको अभी","बताया गया था; अब श्री माताजी कुछ प्रवचन देंगीं।"]],[1335,["श्री माताजी: अब तुम भी तो कुछ बोलो।","सहज योगी: मैंने पहले बोल दिया आपके बारे में।","श्री माताजी: बोल चुके?"]],[1343,["डॉक्टर वॉरेन: क्या आप बैठना चाहेंगी,","श्री माताजी?","श्री माताजी: यहाँ मैं बैठ सकती हूँ।"]],[1409,["जयपुर के सर्व सत्य शोधकों को हमारा प्रणाम।"]],[1421,["जीवन में हर मनुष्य अपनी धारणा के बूते पर","रहता है। जो भी धारणा वो बना लेता है","उसके सहारे वह जीता है।"]],[1437,["लेकिन एक कगार ऐसी ज़िन्दगी में आ जाती","है, जहाँ पर जा कर वह यह सोचता है,"]],[1445,["कि, \"मैंने आज तक जो सोचा, जो धारणाएं","लीं, वो फलीभूत नहीं हुईं।"]],[1451,["उससे मैंने आनंद की प्राप्ति नहीं की, उससे","मुझे समाधान नहीं मिला, उससे मैंने","शांति प्राप्त नहीं की।\""]],[1460,["जब वो कगार मनुष्य के सामने खड़ी हो जाती","है, तब वो अपनी धारणाओं के प्रति शंकित","हो जाता है।"]],[1468,["और उस वक़्त वो ढूँढने लग जाता है कि इससे","परे कौन सी चीज़ है, इससे परे कौन सी"]],[1477,["दुनिया है, जिसे मुझे प्राप्त करना है।"]],[1480,["ये जब शुरुआत हो जाती है, तभी हम कह","सकते हैं, कि मनुष्य एक साधक बन जाता है।"]],[1487,["वो सत्य के शोध में न जाने कहाँ-कहाँ","भटकता है। कभी-कभी सोचता है कि,"]],[1496,["बहुत सा अगर हम धन इकठ्ठा कर लें, तो उस","धन के बूते पे हम आनंद को प्राप्त कर लेंगे।"]],[1504,["फिर सोचता है कि हम सत्ता को प्राप्त कर लें -","सत्ता को प्राप्त करने से ही हम आनंद को","प्राप्त कर लेंगे।"]],[1511,["फिर कोई सोचता है कि अगर हम किसी मनुष्य","मात्र को प्रेम करें, तो उसी से हम सुख को","प्राप्त कर लेंगे।"]],[1522,["उससे आगे जब वो विशालता पे उठता है, तो ये","सोचता है कि, हम प्राणी मात्र की सेवा करें,"]],[1529,["उनकी कुछ भलाई करें, उनके उद्धारार्थ कोई कार्य","करें, तो हम परमात्मा को प्राप्त हो जाते हैं।"]],[1536,["लेकिन ये सब मनुष्य की धारणाएं हैं। मनुष्य","की धारणा से मनुष्य परमात्मा की ओर","नहीं बढ़ सकता।"]],[1544,["क्योंकि परमात्मा असीम हैं और जो सीमित","बुद्धि है, उसके सहारे हम असीम पर उतर","नहीं सकते।"]],[1552,["हमारी आज तक जो उत्क्रांति हुई है, उसके","बारे में अगर हम सोचें, तो सभी कुछ","सहज होते गया।"]],[1561,["आज जो हम आज इंसान बने हैं वो भी सब","सहज हुआ है। हमने उसके लिए कुछ","किया नहीं।"]],[1567,["जो भी कुण्डलिनी आदि का इन्होंने आपसे","बताया, ये सारी चीज़ें जो हैं, ये आपने बनाईं नहीं,"]],[1575,["ये अंदर बनी बनाई रक्खी हुईं हैं। आपके अंदर","स्थित है, आपने इसे अपनी उत्क्रांति में","पाया हुआ है।"]],[1582,["और इस उत्क्रांति में ये पाए हुए इस धन को","आपको सिर्फ पाना है, उसको जान लेना है","और उसका स्वामित्य स्वीकार करना है।"]],[1594,["अब ये चीज़ जो हम कह रहे हैं, ये सच है","या झूठ है, आपके अंदर है या नहीं,"]],[1599,["इसको एक शास्त्रग्न की दृष्टि से अगर देखा जाए,","तो ऐसा ही हम कहेंगे कि जैसे कोई एक धारणा"]],[1606,["शास्त्रग्न बताता है जिसे कि आप कह सकते हैं","हाइपोथिसिस, उसके बाद उस हाइपोथिसिस को"]],[1612,["दूसरा शास्त्रग्न कहता है, 'अच्छा इसको सिद्ध करके","दिखाइए।' अगर वो सिद्ध हो जाये तो उसे फिर"]],[1618,["कायदा माना जाता है। उसे लोग मान","लेते हैं कि ये शास्त्र का कायदा है"]],[1622,["इसलिए वो साइंटिफिक एक मान्य तथ्य हो जाता","है। इसी प्रकार धर्म में भी जब हम किसी चीज़ को"]],[1630,["मान लेते हैं, तो ये ज़रूर जान लेना चाहिए,","कि इस धर्म में जो कुछ वर्णित है,"]],[1634,["वो हम पा रहे हैं या नहीं। लेकिन धर्म के","मामले में हमारी दृष्टि बहुत अंधी है।"]],[1640,["हम ये नहीं सोचते कि जो कुछ भी इसमें","वर्णित है, उसे हमने पा लिया है।"]],[1644,["जैसे कि विशेषकर आज सवेरे ही बातचीत चली थी,","तो मैंने कहा कि, सबसे ज़्यादा हिन्दू लोग अपने","धर्म से बहुत अनभिज्ञ हैं।"]],[1654,["वजह हो सकती है कि इन लोगों को कभी भी","ऑर्गनाइज़ नहीं किया - एक उससे फायदा भी है।"]],[1659,["अगर कोई धर्म आप ज़्यादा से, ज़रुरत","से ज़्यादा ऑर्गनाइज़ कर लिए"]],[1663,["तो आदमी ऐसा बन जाता है जैसे कि किसी बैल को","या किसी घोड़े को आपने आँख के सामने कुछ बाँध","दिया हो।"]],[1672,["लेकिन एक दोष ये भी आ जाता है कि","वो कुछ भी नहीं जानता है।"]],[1678,["इसीलिए हम, जो हमारा धरोहर है, इतने वर्षों से","उपार्जित यहाँ का जो आध्यात्मिक ज्ञान है,"]],[1686,["उससे बिलकुल अपरिचित हैं, उसके बारे में","हम कुछ भी नहीं जानते हैं।"]],[1690,["बड़ी आश्चर्य की बात है, कि कितने ही लोगों को मैंने","जब मैं कुण्डलिनी कहती हूँ, तो वह सोचते हैं कि मैं"]],[1694,["कुंडली की बात कर रही हूँ जिसे कि होरोस्कोप","कहते हैं।"]],[1697,["बहुत ही आश्चर्य कि बात है कि हम अपने","मूल-भूत तत्वों को तक नहीं जानते हैं।"]],[1703,["इस देश में जो इतने सालों से, हज़ारों वर्षों से","कमाया हुआ धन है, उसके बारे में हम","कुछ भी नहीं जानते हैं।"]],[1709,["हमारी दृष्टि ही उस ओर नहीं है, हमारी दृष्टि ही बाह्य","में है, हम उसको जानना ही नहीं चाहते हैं,"]],[1715,["जो हमारा धरोहर, हज़ारों वर्षों से उपार्जित ज्ञान है,","उसके बारे में हम इस कदर अनभिज्ञ हैं,"]],[1726,["उधर कोई उत्कंठा नहीं, कोई विचार नहीं, और","सोचते हैं कि हम लोग मानो, जैसे कोई"]],[1732,["अंग्रेज़ों को ही बनाये हुए कोई पुतले हैं।","इसके अलावा और हम चीज़ सोच नहीं पाते हैं,"]],[1737,["कि कितनी बड़ी परंपरा, कितनी बड़ी सम्पदा","इस देश में हमारे लिए हमारे पूर्वज छोड़ गए हैं।"]],[1745,["अब कहने कि बात ये है, कि हमारे अंदर ये","संस्था पूरी स्थित है, पूरी तरह से विराजमान है।"]],[1756,["लेकिन सत्य को पाने वाले को पहले ये जान","लेना चाहिए, कि जो सत्य है, सो है, उसे आप","नहीं बना सकते हैं।"]],[1762,["आप कहें कि, 'नहीं, हम तो ये सोचते हैं, हमारी","ये धारणा सत्य के बारे में है,' तो वो सत्य","नहीं हो सकता है।"]],[1768,["सत्य जो है सो है। एक नम्र विद्यार्थी की","तरह से आपको ये जानना चाहिए कि,"]],[1774,["'अभी हमने सत्य को जाना नहीं, इसलिए जो सत्य","होगा उसे हम जानेंगे और जानना चाहेंगे।'"]],[1780,["जब तक ये हमारे अंदर विचार जागृत नहीं होता है,","तब तक हमारे अपने ही बनाये हुए पहाड़, बैरियर्स"]],[1787,["(अवरोध) बने हुए हैं उन पहाड़ों को लांघना","बड़ा कठिन हो जाता है।"]],[1791,["सत्य क्या है, सत्य क्या चीज़ है? जिसे हम","कहते हैं 'सत्य, सत्य' - सत्य क्या चीज़ है?"]],[1798,["सत्य एक है सीधा-साधा कि आप आत्मा हैं। आप","शरीर, मन, बुद्धि, अहंकार, आदि कुछ भी नहीं"]],[1805,["आप सिर्फ आत्मा हैं, आप आत्मा हैं और वो आत्मा","का प्रकाश अभी तक आपकी चेतना में, या","आपके चित्त में आया नहीं।"]],[1816,["जिस वक़्त ये आपके चित्त में आ जायेगा, तब","आप जानेंगे कि ये आत्मा हमारे अंदर स्थित है"]],[1822,["क्योंकि आपके नसों में, आपके सेंट्रल नर्वस","सिस्टम(केंद्रीय मज्जा तंतु) में आप इसको","महसूस कर पाएंगे"]],[1828,["इसके लिए आपको कहीं किसी से पूछना नहीं","पड़ेगा, आप इसको खुद जान जाइएगा","कि आपके अंदर"]],[1834,["ये चीज़ चल रही है, ये आपके अंदर बिराजमान है।","अगर मैं आपसे कहूँ कि ये सृष्टि"]],[1840,["[अलग से - आप सामने आ जाइए,","आप सामने बैठिए, आइए, सामने बैठिए]"]],[1845,["ये सृष्टि, चराचर सृष्टि, किसी ऐसे बड़े भारी शक्ति","के साथ चल रही है, जो इस कार्य में पूरी तरह","से सलग्न है,"]],[1857,["तो आपको विश्वास नहीं होगा। किन्तु सोचिये, कि ये","जो फूल बना है, क्या हम ऐसे फूल बना सकते हैं"]],[1863,["क्या इन फूलों से जो फल बनते हैं, वो हम","कर सकते हैं, कोई सा भी जीवित कार्य","हम कर सकते हैं,"]],[1869,["जो कार्य करते हैं सो मरा हुआ। समझ लीजिये,","अगर कोई पेड़ मर गया,"]],[1873,["उससे हमने टेबल बना लिया, तो सोच लिया","बड़ा भरी काम कर लिया। मरे से","मरी चीज़ बना ली।"]],[1877,["और जब मरे से मरी चीज़ बना लेते हैं, तो वो जो","जड़ वस्तु है, वो भी हमारे सर पे बैठ जाती है।"]],[1882,["क्योंकि जड़ और चेतन का हमेशा झगड़ा चलता है।","और आत्मा जो है, उससे जड़ हमेशा भागता है।"]],[1890,["जब आपने एक बार कुर्सी बना ली, तो कुर्सी आपके","सर पे बैठ गई क्योंकि आप कुर्सी के सिवा","बैठ नहीं सकते हैं।"]],[1897,["कुर्सी लेकर आपको घूमना पड़ेगा। जिस चीज़ की,","जड़ की आपने आदत लगा ली, वो जड़ आपकी","खोपड़ी पे बैठ गई।"]],[1903,["इसका मतलब सीधा ये है कि हम जड़ से जल्दी ही","प्रभावित हो जाते हैं बनिस्बत चेतन से।"]],[1910,["और चेतन से भी अगर हो गए, तो भी हम आत्मा के","प्रति उतने उन्मुख नहीं होते हैं, उस तरफ हमारा"]],[1918,["इतना ध्यान आकर्षित नहीं होता है। उसकी वजह","ये है, कि हम अभी तक उतने ऊपर देख","नहीं पाते हैं, उतने उन्नत नहीं हैं।"]],[1927,["अब बहुत से संसार में ऐसे लोग हो गए हैं जिन्होंने","बड़े महत कार्य करके, परमात्मा के बारे में,"]],[1935,["उनके साम्राज्य के बारे में, उनके बड्डपन के बारे में,","कुण्डलिनी के बारे में, सब कुछ बताया हुआ है।"]],[1942,["लेकिन ये किंवदंती ही गई। लोगों को लगता है कि","ऐसी बातें हैं, भगवान-अगवान कोई चीज़ हैं नहीं"]],[1947,["ऐसी बातें चल रहीं हैं, लोग भगवान की बात मात्र","करते हैं और भगवान के नाम पर पैसा खसोटना,"]],[1953,["किसी में झगड़ा लगाना, किसी में परेशानी","में डालना, मंदिरों में चरस बेचना,"]],[1958,["आदि, सब गंदे-गंदे काम करते रहते हैं","और भगवान-अगवान कोई चीज़ नहीं है।"]],[1963,["बुद्धि के स्तर पे बात सही मालूम पड़ती है।","मनुष्य बुद्धि से अगर सोचा जाए"]],[1968,["तो लगता है कि अगर भगवान हैं,","तो ये सब तमाशे क्यों हो रहे हैं।"]],[1973,["इसी प्रकार एक बार अल्जीरिया में बहुत से लोगों ने","ये सोचा कि अगर हम फ़ण्डामेंटालिस्ट( कट्टरपंथी)","लोग"]],[1980,["यहाँ पर आ जाएँ, तो ये लोग आकर के वही","हाल करेंगे जो खोमिनी ने किया हुआ है।"]],[1985,["इस वजह से वहाँ के बहुत से तरुण लोगों ने","ये सोचा, कि बेहतर है कि हम लोग"]],[1990,["कोई कम्युनिज्म को ही प्राप्त करें, उसी का","अवलम्बन करने से ही हम बच सकते हैं।"]],[1997,["तो वो लोग कम्युनिस्ट हो गए - पाँच सौ लोगों","ने अपनी एक कम्युनिस्ट पार्टी स्थापित की।"]],[2002,["उनमें से भूला-भटका लंदन चला आया और सहज","योग में घुस गया। पता नहीं कैसे वो आया बेचारा"]],[2009,["और उसके बाद वो पार हो गया। बहुत ही होशियार","लड़का है, बहुत शुद्ध प्रकृति का लड़का है -"]],[2014,["मुसलमान, लेकिन बहुत शुद्ध प्रकृति का। जब","उसने पाया, उसने जाकर बताया कि, \"नहीं, भगवान","तो हैं, लेकिन अभी हमने पाया नहीं था।\""]],[2024,["पाँच सौ आदमियों को उन्होंने पार करा दिया","और सब को प्लेन से लंदन लाया।"]],[2030,["लेकिन उन लोगों मैं जो उत्कंठा थी, वो बड़ी","ज़बरदस्त थी और गहन सी, बड़ी आंतरिक थी।"]],[2039,["जब तक इस तरह की आंतरिक इच्छा","मनुष्य में सत्य को जानने की न हो,"]],[2044,["तब तक वो सत्य को प्राप्त करके भी खो सकता है।","इसलिए आशा है जयपुर में भी ऐसे लोग बहुत से"]],[2050,["बिराजमान होंगे, कि जो इसको अत्यंत आस्था","से जानना चाहेंगे कि, 'हम क्या हैं, हम इस","संसार में क्यों आये हैं,"]],[2058,["परमात्मा ने हमें क्यों मानव स्थिति दी है,","और इससे परे हमारी कौन सी स्थिति है।'"]],[2063,["इसी को जानना ही सत्य है। जिसने इसे जाना,","वही सत्य है, बाकी तो आदि शंकराचार्यजी ने"]],[2070,["कहा ही हुआ है कि, 'एक आत्मा ही, एक ब्रह्म","ही, सत्य है और बाकी सब भ्रम है।'"]],[2077,["अब ब्रह्म की बात जो है वो इस प्रकार है, कि अभी","जो आप इस चीज़ को जान रहे हैं, समझ लीजिए,"]],[2084,["आप अगर जान रहे हैं कि ये इंसान बहुत","अच्छा है, हो सकता है कि आपको भ्रम हो,"]],[2090,["इसको सोच रहे हैं कि ये बड़े अच्छे गुरु महाराज","जी हैं, हो सकता है कि ये कोई भ्रम हो,"]],[2096,["कोई भी चीज़ आप पूरे सौ फ़ीसदी नहीं कह","सकते कि ये चीज़ बिलकुल सही है।"]],[2102,["वजह ये है, कि अभी तक आपने वो जो एकाकी","चीज़ है, जो एब्सोल्यूट चीज़ आपकी आत्मा है,","उसे नहीं प्राप्त किया।"]],[2109,["क्योंकि जब आप आत्मा को प्राप्त कर लेते हैं","तब आप कोई भी चीज़ को रिलेटिविली,"]],[2115,["यानि इस तरह से नहीं जानते हैं, कि इसका ऐसा है,","तो उसका वैसा है (बट) लेकिन पूरी तरह से","जानकारी रखते हैं कि यही चीज़ सही है।"]],[2123,["लेकिन उसका मार्ग क्या होना चाहिए? हमारे","उत्क्रांति में हमने उसका मार्ग कैसे पाया है।"]],[2130,["जैसे कि एक जानवर है उससे आप कहिए कि","किसी गन्दी गली से चले जाओ, तो वो चला जायेगा।"]],[2136,["उसको कोई ये प्रश्न नहीं खड़ा होगा, कि इसमें बदबू","आ रही इसमें गंदगी है, कुछ है, वो अपना","सीधे-सीधे चला जायेगा।"]],[2142,["पर एक इंसान से कहिए तो वो नहीं जा सकता है।","वजह ये है कि आपकी जो सगन्या है,"]],[2148,["आपकी जो केंद्रीय तंत्रिका तंत्र है (सेंट्रल नर्वस","सिस्टम) उसपर आप महसूस करते हैं","कि ये गंदगी है।"]],[2153,["ये आपने अपनी उत्क्रांति में पाई हुई चीज़ है।","जो चीज़ आपने पाई है वो आपने सेंट्रल","नर्वस सिस्टम में पाई है,"]],[2161,["और इसी प्रकार आत्मा को भी आपको","सेंट्रल नर्वस सिस्टम में पाना चाहिए।"]],[2166,["नहीं तो अपने को ही लोग कहें, 'हम बड़े हैं, हमने","पा लिया है, हम पहुँचे हुए हैं, हम पार हैं,'"]],[2173,["इस तरह से अपने को ही सर्टिफिकेट कोई","दे दे, तो वो मानने की बात नहीं।"]],[2178,["लेकिन जब कोई चीज़ ऐसी हो जाती है, तो","उसकी शक्तियाँ भी प्राप्त होनी चाहिए।"]],[2183,["माने ये कि अगर कोई कहे कि, 'मैं गवर्नर हूँ,' तो","उसके पास अपनी शक्ति होती है गवर्नरशिप की।"]],[2189,["इसी प्रकार जब अपनी आत्मा को आप प्राप्त होते","हैं, तो उस आत्मा की शक्ति को आप प्राप्त होते हैं।"]],[2195,["अगर उस शक्ति को आप अपने सेंट्रल","नर्वस सिस्टम, फिर मैं कहूँगी,"]],[2198,["अगर प्राप्त नहीं कर सकते, सिर्फ दिमागी","जमा-खर्च है, तो वो शक्ति नहीं।"]],[2204,["माने सबसे पहले आपको सामूहिक चेतना प्राप्त","होती है। सामूहिक चेतना, जिसे कि कलेक्टिव","कॉन्ससियसनेस कहते हैं,"]],[2212,["जिसमें आप दूसरों के चक्रों को जान सकते हैं,","अपने भी चक्रों को जान सकते हैं,"]],[2219,["क्योंकि सबसे पहले तो आप अपने ही को प्राप्त","होते हैं, अपनी आत्मा को प्राप्त होते हैं।"]],[2223,["जिसको कहते हैं सेल्फ रियलाईज़ेशन, माने अपने","सेल्फ ही को आप जानते हैं, कि आपके अंदर","क्या दोष है।"]],[2229,["दूसरी चीज़ है, आप अपने उँगलियों के इशारों पर","जान सकते हैं, कि दूसरों में क्या दोष है।"]],[2235,["यही सामूहिक चेतना का अपने सेंट्रल नर्वस सिस्टम","पे जागृत होना, अपने मज्जा तंतुओं पे जागृत","होना ही आत्मसाक्षात्कार है।"]],[2246,["ज़बानी जमा-खर्च नहीं है, तर्क-वितर्क नहीं है,","शब्द-जाल नहीं है, किसी का कुछ कह देना कि,"]],[2252,["'तुम ये योगानंद हो गए, भोगानन्द हो गए, उससे","नहीं होता है। कोई सर्टिफिकेट से नहीं होता है","- ये अंतर्योग है।"]],[2258,["ये क्रिया जीवंत क्रिया है, जीवंत शक्ति की क्रिया है,","जो जीवंत मनुष्य में होती है और जो उसमें","पूरी तरह से"]],[2268,["उसका प्रत्यय देती है, उसका प्रमाण देती है।","किन्तु हम लोग कोई भी बाह्य चीज़ों में","पहले लिपट जाते हैं।"]],[2280,["ये एक अंदर से होने वाली घटना है। अब जैसे","बहुत से लोग हैं, कहते हैं कि गेरुआ वस्त्र","पहनना चाहिए।"]],[2287,["गेरुआ वस्त्र पहनने से आप सन्यासी हो जाएंगे।","बाह्य के दो रुपए में अगर कपडा आप रंगा लें,","तो क्या आप सन्यासी हो जाएंगे?"]],[2297,["गेरुआ वस्त्र पहन के आप सब की प्रॉपर्टी","मारते फिरते हैं। आप सन्यासी कहाँ से हो गए?"]],[2303,["आपकी नज़र तो सारी सब के जेब पर है,","आप सन्यासी कैसे हो गए?"]],[2308,["गेरुआ वस्त्र किसलिए पहना जाये","- अंदर का गेरुआ पहनिए।"]],[2312,["जब आपने अंदर से गेरुआ पहन लिया, तो बाह्य","में तो आप राजा जनक जैसे विदेही हो जाते हैं।"]],[2320,["फिर जहाँ भी रहिए, चाहे महलों में रहिए, चाहे","जंगलों में रहिए, कहीं भी रहिए - आप बादशाह हैं।"]],[2325,["माने दुनिया की कोई सी भी चीज़ आपको जीत नहीं","सकती, कोई भी चीज़ आपको खींच नहीं सकती"]],[2330,["आप किसी के सामने झुक नहीं सकते,","कोई आपको खरीद ही नहीं सकता है।"]],[2333,["ऐसे अनमोल हीरा जब होते हैं, तभी","मानना चाहिए कि आदमी पहुँचे हुए हैं।"]],[2337,["नहीं तो जो देखे वो ही आपको खरीद ले। जो देखे","आपको रुपए से खरीद ले या किसी और","चीज़ से खरीद ले।"]],[2342,["तो फिर आपमें और दूसरों में क्या अंतर रह गया?","मैं तो कहती हूँ दूसरों से भी गए बीते आप हैं"]],[2347,["कि आप दूसरों के पैसे पे जी रहे हैं। कम से","कम जो मनुष्य संसार में रहता है,"]],[2352,["वो अपने ही तो कमाई पे जी रहा है, दूसरों","की कमाई पे तो नहीं जीता है।"]],[2356,["सन्यासी वस्त्र पहन कर के आप दूसरों की कमाई","पे जी रहे हैं, तो इससे फायदा ये, कि वस्त्र को छोड़","के कायदे से कमाई करिए।"]],[2363,["पर अधिकतर लोग, जो और कोई कमाई नहीं कर","सकते, वही इस तरह की कमाई करते हैं।"]],[2368,["लेकिन हमारे बुद्धि में भ्रम है, कि हमने जैसे ही","काषाय वस्त्र देखा, हो गया उसके पीछे","हम लोग लट्टू।"]],[2374,["खासकर हमारी लेडीज में ये खासकर बात है।","आज ही मैंने देखा कि सब औरतें जिनके गुरु थे,","वो पार नहीं हुए, उनके पति लोग पार हो गए।"]],[2383,["धर्म के प्रति जब हमारी दृष्टि उठती है तो इस प्रकार","कि जब हम गलत चीज़ है, उसी को मान लेते हैं -","ये तामसिक प्रवृत्तियाँ हैं।"]],[2391,["और जब धर्म से हमारी प्रकृति हटती है, तो हम","यही नहीं जानते कि सही क्या और गलत क्या।"]],[2397,["इसी दुविधा में रहते हैं कि सही क्या गलत क्या?"]],[2399,["जैसे कि पाश्चिमात्य देशों में लोग हैं, उनको","यही नहीं पता है कि सफ़ेद क्या और काला क्या?"]],[2406,["ऐसे लोगों को यही कहा जाता है, कि सिर्फ","अहंकार के बूते पे जो आदमी चलता है,"]],[2412,["वो यही कहता है कि, 'मुझे ये पसंद है","इसलिए ये अच्छा है, मुझे ये पसंद है।'"]],[2415,["पर कौन है वो जो उसे पसंद है","- वो तो तुम्हारा सिर्फ अहंकार है।"]],[2421,["जब अहंकार खुश होता है, तो आदमी कहता है","कि, 'मैं तो आज सुख में हूँ।'"]],[2427,["जिस दिन अहंकार दुखता है, तो कहता है,","'मैं दुःख में हूँ।'"]],[2430,["अहंकार के बूते पे रहने से, मनुष्य इसी चक्कर में","पड़ा रहता है, 'पल में तोला पल में मासा।'"]],[2437,["लेकिन जब आप अपने आत्मा पर आ जाते हैं,","तो आत्मा सत्य स्वरुप तो है ही, लेकिन ये","आनंद स्वरुप भी है।"]],[2445,["यही आनंद दायक है और आनंद किसी से","नहीं प्राप्त हो सकता। अगर कोई कहे कि,"]],[2451,["'मेरे पति अच्छे नहीं हैं, मेरी पत्नी अच्छी नहीं है,","मेरे बाप अच्छे नहीं, मेरी माँ अच्छी नहीं,"]],[2456,["इसलिए मैं दुखी हूँ या समाज के कारण मैं दुखी हूँ,'","तो जान लेना चाहिए, इसलिए आप दुखी नहीं हैं,"]],[2466,["आपने वो स्त्रोत पाया नहीं जिससे कि आनंद","मिलता है; वो है आपका आत्मा, जो आप","ही के अंदर निहित है।"]],[2472,["इस आत्मा को प्राप्त करना चाहिए, जिसके","अंदर सुख दुःख की दुविधाएं नहीं हैं -"]],[2478,["जो सिर्फ निरानंद है । उस निरानंद को प्राप्त करना","चाहिए, क्योंकि सुख दुःख के झमेले में पढ़कर के","मनुष्य कभी सुख में कभी दुःख में चलता है।"]],[2489,["वो अविनाशी चीज़ नहीं है। एक बार इसका विनाश","होता है, कभी उसका विनाश होता है।"]],[2495,["इसलिए मनुष्य को, आत्मा का जो स्वरुप","आनंद है, उसे प्राप्त होना चाहिए।"]],[2500,["सत्य सरूप आनंद ऐसे हैं, कि जिस वक़्त आप","आत्मा को प्राप्त होते हैं, आप के हाथ पर आप","जान सकते हैं सत्य क्या है।"]],[2507,["समझ लीजिए आप से कहा गया कि, 'फलाने","मंदिर में स्वयंभू देवता हैं।'- समझ लीजिए"]],[2514,["अब किसी ने कह दिया तो हो गया। हो सकता है","कि उसी ने लाकर के वहाँ बिठा दिए हो,","कहे स्वयंभू आ गए।"]],[2520,["कैसे जानिएगा कि ये स्वयंभू हैं?","कैसे पहचानियेगा कि ये स्वयंभू हैं?"]],[2524,["उसको पहचानने का तरीका ये है, कि जब आप","आत्मा से प्राप्त होते हैं, तब आपके अंदर से","चैतन्य की लहरियाँ,"]],[2532,["जिसे कि सौंदर्य लहरी कर के आदि शंकराचार्य","ने वर्णित किया है, आपके अंदर से बहने","लग जातीं हैं।"]],[2538,["और आप उसे जान सकते हैं कि ये असल है या","नक़ल है। एक बार हम लोग कश्मीर गए थे।"]],[2545,["कश्मीर में घूमते-घूमते एक जगह बड़ी ज़ोर की","मुझे चैतन्य की लहरियाँ महसूस हुईं,"]],[2552,["तो मैंने ड्राइवर से पूछा, 'यहाँ कोई बड़ा पुराना","मंदिर हैं किसी का।' कहने लगे, 'नहीं,","ये तो जंगल है।'"]],[2557,["मैंने कहा, 'अच्छा, चलो इस तरफ चलो।'","रास्ते से गुज़रते-गुज़रते आगे गए"]],[2560,["तो कुछ गरीब मुसलमानों की झोपड़ियाँ-ओपड़ियाँ","दिखाई दीं। तो उनसे पूछा, \"भई, यहाँ कोई","मंदिर-वंदिर है।\""]],[2566,["तो, 'नहीं।' कहने लगे कि, 'यहाँ एक चीज़ है,","हज़रतबल।' मैंने कहा, 'अच्छा।'"]],[2571,["मोहम्मद साहब का एक बाल वहाँ रखा हुआ था;","पाँच मील दूरी पर उसको मैंने पकड़ा।"]],[2577,["अब ये मुसलमान भी नहीं जानते हैं जो उसके लिए","लड़ते हैं। नमाज़ पूरा कुण्डलिनी का जागरण है।"]],[2584,["मोहम्मद साहब का वर्णन अपने शास्त्रों में महामेधा","करके है। लेकिन ये मुसलमान क्या जानें और","हिन्दू क्या जानें"]],[2590,["जब तक आत्मा को प्राप्त हम नहीं करेंगे, तब","न हम कृष्ण को जानें और न ही हमने राम","को जाना है।"]],[2596,["जब वो अकबर की बात करते हैं, तो श्री कृष्ण","की बात करते हैं, विराट की।"]],[2601,["क्या हम जानते हैं कि उनका और उनका","बड़ा घनिष्ट सम्बन्ध है।"]],[2604,["ईसा मसीह ने साफ़ कहा था कि, 'जो","मेरे विरुद्ध नहीं हैं वे मेरे साथ हैं।'"]],[2609,["ये लोग कौन हैं। ईसाई लोग कभी इस बात को","सोचभी नहीं सकते, कि साक्षात् महाविष्णु ही।"]],[2615,["इनका वर्णन देवी माहात्म्य में आता है। शायद बहुत","कम लोगों ने पढ़ा होगा - वही साक्षात्","जीसस क्राइस्ट थे।"]],[2623,["और जीसस का नाम येसु है - येसु, यशोदा से, और","क्राइस्ट, कृष्ण से, उनकी माँ ने उनका रखा था।"]],[2630,["लेकिन इसको समझने के लिए, सबसे पहले","आत्मा को आप प्राप्त हों।"]],[2634,["जिस वक़्त आपमें आत्मा की प्राप्ति होगी, आप देख","सकते हैं, कि जो हम कह रहे हैं, सच है, झूठ है।"]],[2640,["अगर झूठ हो, तो आपके अंदर के चैतन्य बंद","हो जाएंगे; अगर सच हो, तो बहना शुरू हो जाएंगे।"]],[2646,["अगर आप ये पूछें, कि परमात्मा है या नहीं, तो हाथ","में ठंडी-ठंडी हवा ज़ोर से चलनी शुरू हो जाएगी।"]],[2653,["और अगर किसी गलत आदमी के लिए","आप पूछें, कि ये आदमी सही है या नहीं,"]],[2656,["तो सामूहिक चेतना पर","आप जान जाइएगा कि ये आदमी कैसा है।"]],[2661,["कभी-कभी हो सकता है हाथ में एक-आद","ब्लिस्टर भी आ जाये।"]],[2663,["कल भी मेरे हाथ में एक ब्लिस्टर आ गया","क्योंकि कोई गलत आदमी किसी गलत गुरु","का आया हुआ था,"]],[2671,["तो एक छोटा सा ब्लिस्टर आ के समझा गया","कि ये आदमी गलत गुरु के पास जाता रहा है।"]],[2678,["इस तरह से आप जान सकते हैं कि कौन सही है,","कौन गलत है, बिलकुल अपनी ही चेतना में,"]],[2684,["अपनी ही अवेयरनेस में, अपनी ही केंद्रीय तंत्रिका","तंत्र में, आप जान सकते हैं कि कौन सही है,"]],[2690,["कौन गलत है, कौन सत्य है, कौन असत्य है। हर","प्रकार का सत्य-असत्य आप इस पर","जान सकते हैं।"]],[2697,["जैसी-जैसी आपकी उन्नति होती है, आप इतनी","चीज़ें जान सकते हैं, जिसका आपको अंदाज़","नहीं हो सकता है।"]],[2705,["यहाँ बैठे-बैठे आप सब चीज़ जान सकते हैं।","वजह ये है, कि जो आपकी टेलीकम्युनिकेशन्स"]],[2711,["(दूरसंचार) वगैराह हैं, इसकी भी कल्पना उसी","जो सर्वव्यापी टेलीकम्यूनिकेशन है,","उसी से आई हुई है।"]],[2718,["जब वो सर्वव्यापी टेलीकम्यूनिकेशन में आप उतर","जाते हैं, तो सारे सृष्टि की जितनी चीज़ है, उसको"]],[2723,["आप समझ सकते हैं, इसीलिए कहा जाता है कि","द्रष्टा। मार्कण्डेय को देखिए तो किस कदर द्रष्टा थे"]],[2731,["लेकिन अभी हमने सौ साल पहले के एक बड़े","भारी दृष्टा का ज्ञान पाया जो कि लंदन में थे।","उनका नाम था विलियम ब्लेक।"]],[2742,["उन्होंने सहज योग के बारे में इतनी गहरी","बातें लिख छोड़ीं हुईं हैं, सौ साल पहले,"]],[2747,["कि लंदन में ये कहाँ होगा, इसके स्कूल","कहाँ होएगा, इसका कॉलेज कहाँ होगा,"]],[2751,["इसका आश्रम कहाँ होगा, मेरा घर कहाँ होगा, मैं","कहाँ रहूंगी पहले, फिर उसके बाद कहाँ जाऊँगी।"]],[2759,["हैरानी हो जाती है; इतने बड़े द्रष्टा थे और","अँगरेज़ लोग कहते हैं कि वो पागल थे।"]],[2765,["अंग्रेज़ों के तो कभी समझ में नहीं आने वाले","साधु-संत। उनका तो दिमाग ही ख़राब है।"]],[2771,["लेकिन हम, जिन्होंने कितने साधु-संतों को","जाना है, या तो वो झूठ बोलते थे -"]],[2777,["और अगर वो सच बोलते थे, तो अपने आत्मा का","हमें विचार करना चाहिए, कि हमने अपने","आत्मा को प्राप्त किया है या नहीं।"]],[2784,["ये शब्द जाल नहीं होना चाहिए।अगर कोई आकर","के आपके सामने शब्द जाल फैलाता है,"]],[2788,["बातचीत करता है, मनोरंजन आपका करता है,","तो आप उसी से पूछो जाके।"]],[2793,["इस तरह से आप अपनी जो आध्यात्मिक दृष्टि है","उसको कितनी छोटी कर लेते हैं।"]],[2800,["आध्यात्मित दृष्टि वहाँ तक रखनी चाहिए, जहाँ","तक आत्मा का स्थान है। जब तक हमने"]],[2806,["आत्मा को प्राप्त किया नहीं, तब तक हमारी","आध्यात्मिक तृष्णा कभी भी तृप्त नहीं हो सकती है।"]],[2811,["इसके लिए आपके रीढ़ की हड्डी के सबसे नीचे के","हिस्से में, जिसे हम लोग सेक्रम बोन कहते हैं,"]],[2819,["उसके अंदर त्रिकोणाकार अस्थि में","कुण्डलिनी नाम की शक्ति है।"]],[2824,["ये शक्ति साढ़े तीन वलय में है, कुण्डलों","में है, इसलिए इसे कुण्डलिनी कहते हैं।"]],[2832,["आपको आश्चर्य होगा, कि ग्रीस में हम जब गए,","तो अथीना - ये 'अथ' शब्द से आया -","अथ माने प्राइमॉर्डिअल -"]],[2840,["प्रीमॉर्डिअल मदर अथीना है और उसके हाथ में","साँप के साढ़े तीन ये करके, चक्र देकर के,","हाथ में कुण्डलिनी है।"]],[2848,["उसका वहाँ पर न जाने कितने ही उसके स्टैचूस","बने हुए हैं। और जब उसके मंदिर पे पहुँचे,","तो बाहर गणेश जी की मूर्ती बनाई बैठी हुई है।"]],[2856,["मैंने पूछा कि, \"भई ये कौन?\" कहने,","\"यह बाल देवता हैं।\""]],[2861,["तो मैंने कहा, \"ये किसने बताया आपसे?\"","कहने लगे, \"हिन्दुस्तानियों ने बताया।\""]],[2865,["मैंने कहा, \"कब, जब एलेग्जेंडर आया था तब?\""]],[2867,["\"नहीं, नहीं एलेग्जेंडर तो बहुत बाद में गए थे।","हज़ारों वर्ष पूर्व हमारा हिन्दुस्तानियों से","सम्बन्ध रहा।\""]],[2873,["उन्होंने तो उस चीज़ को जोड़ लिया और हमको","यही नहीं मालूम कि कुण्डलिनी क्या चीज़ है।"]],[2878,["इतना ही नहीं, आपको आश्चर्य होगा कि, उसकी जो","सीढ़ियाँ हैं, वो भी उन्होंने कहा, 'ये साढ़े तीन हैं।'","मैंने कहा, \"क्यों?\""]],[2885,["कहने लगे, \"अथीना की जो शक्ति है,","वो साढ़े तीन राउंड्स में है,"]],[2889,["और अगर इस राउंड्स को आप पूरा","करिएगा, तो ये सारी पृथ्वी पर चली जाएगी।"]],[2897,["ये साढ़े तीन क्यों है, इसका एक गणित है।","इस गणित के वजह से ये साढ़े तीन है।"]],[2903,["हमें इसे, हम लोग कहते हैं महाकाली,","महालक्ष्मी, महासरस्वती और आदिशक्ति","की अर्ध मात्रा।"]],[2910,["इस प्रकार से ये साढ़े तीन कुण्डलिनी है। अब","अगर आजकल के पढ़े लोगों के सामने"]],[2915,["महाकाली, महालक्ष्मी की बात करें, तो लोग","कहेंगे कि, \"माँ कहाँ की, बाबा आदम के ज़माने","की बात कर रहीं हैं।\""]],[2920,["पर जो बाबा आदम के ज़माने की बात है, वो","सब सच्ची है और वो सच्ची चलती रहेगी, उसकी","सिर्फ सिद्धता आपको हमें देने की है।"]],[2927,["ये बात सिद्ध है या नहीं, ये सही बात है नहीं जो","हमारे पूर्वजों ने बात करी, ये झूठ करी या सही कही","ये आज आपको सिद्ध करके देने का है।"]],[2936,["पर ये आप ही से सिद्ध होगा। आप ही के अंदर","जब आत्मा जागृत होएगी, तभी ये सिद्ध हो","सकता है, नहीं तो नहीं हो सकता है।"]],[2944,["ये जो शक्ति है शुद्ध इच्छा है। बाकी जितनी","भी हमारी इच्छाऐं है, अशुद्ध हैं।"]],[2950,["आपने इकोनॉमिक्स (अर्थशास्त्र) का लॉ","(नियम) जाना है कि,"]],[2953,["'व्यक्तिगत इच्छाएँ संतुष्ट हो सकती हैं, लेकिन","सामान्यतः इच्छाएँ संतुष्ट नहीं हो सकतीं।'","तृप्त करने योग्य नहीं"]],[2962,["इसका मतलब ये है, कि हमारी इच्छाएँ","अगर शुद्ध हों तो वो इच्छा जब,"]],[2968,["जो इच्छा अगर शुद्ध इच्छा हो, तो उसके बाद","कोई इच्छा ही नहीं रहनी चाहिए।"]],[2972,["लेकिन क्योंकि इच्छा शुद्ध नहीं थी, इसलिए एक","इच्छा हुई, फिर दूसरी इच्छा हुई"]],[2977,["- आज हुआ मकान बनाओ, कल घर बनाओ,","फिर तीसरा हेलीकाप्टर खरीदो।"]],[2981,["लेकिन जो शुद्ध इच्छा की शक्ति है वो एक है,","और वो इच्छा ये है, कि हमारा योग इस","सर्वव्यापी शक्ति के साथ होना चाहिए।"]],[2991,["यही शुद्ध इच्छा है। जब तक ये शुद्ध इच्छा","पूरी तरह से प्लावित नहीं होती,"]],[2997,["तब तक कोई सी भी दुनिया की इच्छा से हम","आनंद को प्राप्त नहीं कर सकते हैं।"]],[3001,["लेकिन जैसे कल मैंने बताया कि योग के दो अर्थ","होते हैं। एक तो अर्थ होता है 'योग' माने जोड़ना"]],[3010,["हमारे आत्मा से हमारा कुण्डलिनी का योग, या","हमारे अंदर हमारे चित्त में सारी सर्वव्यापी शक्ति","से योग होना - एक ये योग हुआ"]],[3028,["और दूसरा अर्थ योग का होता है, कौशलम माने","एक्सपरटाइज़। एक बार ये शक्ति हाथ में","लगने के बाद,"]],[3036,["ये आपको जानना चाहिए कि ये शक्ति क्या है,","इसका असर क्या है, इसका उपयोग क्या है,"]],[3042,["इसको कैसे इस्तेमाल करना चाहिए और","इसका लाभ किस तरह से हो सकता है।"]],[3047,["क्योंकि सहज योग जो है आज समाजोन्मुख है","- एक दो व्यक्तियों के लिए आज सहज योग","नहीं है।"]],[3053,["हज़ारों व्यक्तियों को पार करना है - हज़ारों","व्यक्ति पार हो सकते हैं, ऐसा ये सहज योग है।"]],[3059,["एक आदमी को बैठा के पार करने की कोई बात","नहीं रह गई कि व्यक्तिगत हो - ये","समाजोन्मुख है।"]],[3065,["क्योंकि इसके लाभ समाज को होते हैं। सबसे","पहले तो तंदरुस्ती इंसान की ठीक हो जाती है"]],[3070,["बगैर पैसे के, बगैर डॉक्टर के, बगैर","डायग्नोसिस के, बगैर किसी चीज़ के।"]],[3075,["मानसिक स्थिति ठीक हो जाती है, साम्पत्तिक","स्थिति ठीक हो जाती है, क्योंकि लक्ष्मी का तत्व","ठीक हो जाता है।"]],[3081,["हमारे देश में लोग कहते हैं, कि आपके अंदर","इतनी योग शक्ति है, आप लोग इतने योगी हैं,","इतने आध्यात्मिक हैं, आप गरीब क्यों हैं?"]],[3089,["क्योंकि हमारे देश में कभी किसी ने योग","प्राप्त नहीं किया।"]],[3094,["कोई पॉलिटिशियन ने कभी योग प्राप्त नहीं","किया, बेकार के चक्करों में घूमते रहे","- आज तक किसने योग प्राप्त किया है?"]],[3102,["जब अपने देश में योग की प्राप्ति होएगी, तो श्री","कृष्ण ने साफ़ कहा है कि, 'योगक्षेम वहामायम।'"]],[3107,["पहले योग को प्राप्त करो। जब सुदामा जी","श्री कृष्ण से मिलने गए तभी उनको","क्षेम प्राप्त हुआ।"]],[3114,["इसी प्रकार जब तक हम परमात्मा के साम्राज्य","में नहीं जाते हैं, ये परमात्मा की ज़िम्मेदारी नहीं","रह जाती कि वो हमारे क्षेम को देखें।"]],[3122,["अभी तो आप जिनके राज्य में बैठे हैं ये","उनकी ज़िम्मेदारी है।"]],[3127,["जिस वक़्त आप परमात्मा के साम्राज्य में उतरेंगे,","तब वो परमात्मा की ज़िम्मेदारी हो जाती है"]],[3133,["कि वो आपको क्षेम प्रदान करते हैं। इसका","मतलब ये नहीं कि आप पे रुपया ही बरसाते","हैं - वो तो बहुत गलत चीज़ हो जाएगी।"]],[3139,["लेकिन ऐसी स्थिति आप प्राप्त करते हैं,","कि समाधान में आप इतना प्राप्त होते हैं,"]],[3144,["कि किसी तरह से आपको कोई चीज़ की दिक्कत","नहीं रह जाती और अब कोई मांग नही।"]],[3149,["\"अब कुछ नहीं चाहिए, माँ हम आनंद के सागर","में तैर रहे हैं,\" ऐसा आप कहने लग जाते हैं।"]],[3155,["इतना ही नहीं, आपके अंदर धर्म जागृत हो जाता","है। अगर आपसे मैं कहूँ कि, \"ये न करो, वो न","करो, तो आप ज़रूर करेंगे।\""]],[3162,["इंसान की यही ख़ास चीज़ है। अगर कहा जाए","कि, \"आप ये नहीं करो,\" तो क्यों न करूँ,","वो ज़रूर करेंगे।"]],[3168,["इसलिए बेहतर है आपके अंदर कुण्डलिनी जागृत","कर दें, आपके अंदर धर्म की जागृति हो जाये","और आप स्वयं ही धार्मिक बन जाएँ।"]],[3176,["यानी ईसा मसीह को ये नहीं बताना पड़ता था,","कि तुम गलत काम मत करो।"]],[3181,["वो स्वयं ही नहीं करते थे। इसी प्रकार आपके","अंदर स्वयं ही धर्म जागृत हो जाता है,","हमें कुछ कहना नहीं पड़ता है।"]],[3188,["आज का सहज योग यही विशेष है, कि किसी","भी तरह का क्यों न हो इंसान, उसकी पहले","कुण्डलिनी जागृत कर दो।"]],[3195,["थोड़ा सा भी टिमटिमाता भी प्रकाश उसके","अंदर अगर घूमने लग जाये, तो वो देखेगा,","मेरे अंदर क्या गड़बड़ी है।"]],[3200,["उसी को उसका गुरु बना दो वो अपने को ठीक","करता रहे, जिससे मुझसे झगड़ा न हो।"]],[3206,["वो खुद ही जानेगा कि ये दोष मेरे अंदर है,","खुद ही ठीक करेगा अपने को।"]],[3211,["जब कभी हाथ में दिखाई दे कि साँप है, तभी न","साँप को फेंकियेगा; अगर कहेंगे, \"साँप है,\"","तो आप फेंकने वाले नहीं।"]],[3218,["इसलिए थोड़ा सा न क्यों प्रकाश इंसान के","अंदर अगर हो जाये, तो वो देखने लग जाता","है कि प्रकाश कोई चीज़ है।"]],[3224,["और इससे परे कोई ब्रह्म शक्ति है। जब उसे वो","जानने लग जाता है तो अपने आप ऐसी चीज़ें,"]],[3232,["जिसे वो पहले गलत नहीं समझता, एकदम","से ही फेंक देता है। ये चीज़ घटित होनी चाहिए।"]],[3239,["जब तक कि ये चीज़ घटित नहीं होती है, भाषणों","से, समझाने से, उपदेशों से, कुछ भी चीज़","होने वाली नहीं।"]],[3247,["आज सहज योग उस स्तर पे है, जहाँ पे मैं कह","सकती हूँ, कि बहुत जल्दी इस का असर","लोगों को मालूम पड़ेगा।"]],[3255,["लेकिन दुर्भाग्यवश आज तक मैं जयपुर नहीं आ","सकी। और जयपुर आई भी हूँ तो उस सही दिन,"]],[3263,["जिसको कि हम गुड़ी पाड़वा मराठी में कहते हैं,","जो शालिवाहन राजा ने हिंदुस्तान में बनाया था।"]],[3268,["लेकिन वो असल में, आप जानते हैं, महाराष्ट्र","में राज्य करने गए थे और ख़ास उनका","वंश जयपुर का था।"]],[3275,["उसी दिन मैं यहाँ आई हूँ और मैं उसी वंश","की हूँ, मैं भी राजपूत ही हूँ"]],[3279,["लकिन अब बहुत सालों से, हज़ारों वर्ष से वहाँ रहने","की वजह से, शालिवाहन के सब वंशज","महाराष्ट्रियन हो गए।"]],[3285,["एक तरह से अच्छा भी है, क्योंकि महाराष्ट्र में","जितना कुछ लोग कुण्डलिनी के बारे में जानते हैं"]],[3290,["सारे हिंदुस्तान में क्या, दुनिया में कोई नहीं","जानता है। वहाँ पर नाथ पंथियों ने इतनी","मेहनत करके रखी हुई है -"]],[3295,["मराठी भाषा में कुण्डलिनी के बारे में जितना","लिखा हुआ है, किसी भाषा में लिखा हुआ","आप नहीं प्राप्त करिएगा।"]],[3301,["हाँलाँकि कबीरदास जी ने काफी लिखा,","लेकिन कोई पढ़ता थोड़े ही है।"]],[3304,["वो तो अखंड पाठ होता है, उसमें चलते रहता है","अपना अखंड पाठ। एक आया, उसने ऊँगली","रखी, 'भई, तू अब पढ़।'"]],[3310,["फिर वो आया उसने ऊँगली रखी। बस ये कि","अखंड पाठ चलता रहे। उसके अंदर क्या है","कोई सोचता नहीं।"]],[3316,["नानक ने लिखा है कि, 'कहे नानक बिन आपा चीन्हे","मिटे न भ्रम की काई।\" गा रहे हैं, 'भ्रम की","काई, मिटे न भ्रम की काई।'"]],[3325,["अरे भई जो दवा लिख के गए हैं वो लो। दवा जो","दिए हैं वो ही प्रिस्क्रिप्शन लेकर के घूमोगे,","तो फायदा क्या होगा?"]],[3330,["कि वो ही प्रिस्क्रिप्शन कह रहे कि, 'मिटे न","भ्रम की काई।' लेकिन लेगा कौन, करेगा कौन?"]],[3337,["सब ने कह दिया है, कि अपना आत्मसाक्षात्कार","प्राप्त करो। जो हम हिन्दू बनते हैं,"]],[3344,["इनके जो प्रवर्तक आदि शंकराचार्य, उन्होंने हर","बार यही कहा है कि, 'ना योगे ना सांख्ये'"]],[3351,["ये सब बेकार चीज़ें छोड़ो, पहले आत्मा को","प्राप्त करो - माँ की कृपा से ही ये होता है।"]],[3357,["लेकिन उनको लोग कहाँ मानते हैं? पता नहीं","कौन सा वितंडवाद करते बैठे हुए हैं, पता नहीं","कौन सी चीज़ शुरू की है?"]],[3365,["जो सारे इसका मूलभूत तत्व है, वो अब हिन्दू धर्म में","होते हुए भी, हिन्दू धर्म को एक अजीब तरह का","झगड़े का माध्यम बना लिया है।"]],[3377,["जो कि सारी दुनिया की शांति का माध्यम","हो सकता है, सारी दुनिया को सुख"]],[3383,["और सारी दुनिया का जो मार्गदर्शन कर सकता","है, उसको एक तलवार बना के घुमा रहे हैं, जो कि","सारी दुनिया की ढाल हो सकती है।"]],[3393,["बड़ा मुझे आश्चर्य होता है कि हो क्या","रहा है? इसके मूलभूत तत्व को तो"]],[3397,["आपके बड़े-बड़े लीडरों से बात करने पर आश्चर्य","होता है, कि इनको तो मालूम ही नहीं है कि"]],[3400,["सारे इसका मूलभूत तत्व है, आत्मा को प्राप्त","करना और कुण्डलिनी का जागरण।"]],[3406,["इतने स्पष्ट रूप से किसी भी धर्म पुस्तकों में नहीं","लिखा गया है जितना अपने शास्त्रों में","लिखा गया है।"]],[3413,["और जगह लिखा है - जैसे बाइबिल में बहुत","जगह लिखा है कि इसको ट्री ऑफ़ लाइफ","(जीवन का वृक्ष) कहा गया है।"]],[3418,["'मैं आग की लपटों की तरह तुम्हारे सामने","उपस्थित होऊँगा,' कहा गया है।"]],[3420,["बहुत कुछ बातें कहीं हैं, लेकिन साफ़ एक-एक","सिलसिले से बात जितनी मार्कण्डेय ने कही,"]],[3427,["आदि शंकराचार्य ने कही या कबीरदास जी,","नानक जी ने कही, उतनी किसी ने नहीं कही।"]],[3431,["लेकिन उधर किसका चित्त है। हमारा तो चित्त","ऐसी जगह ही जाता है जाना नहीं चाहिए।"]],[3438,["क्योंकि इन लोग का जैसे मैंने बताया है, सारा","जो कुछ भी हुआ है, ये बाह्य का है। जैसे","कि एक पेड़ बढ़ जाता है"]],[3445,["और उसके, वृक्ष के इतने बढ़ने पर भी, जब","उसकी जड़ें अंदर उतरतीं नहीं,"]],[3451,["तो उसको गिरने की आशंका हो जाती है। इसी","शॉक में आपका सारा वेस्टर्न वर्ल्ड","आज बैठा हुआ है।"]],[3457,["लेकिन हिंदुस्तान में इसकी जड़ें हैं,","इसका सारा धरोहर हिंदुस्तान में है,"]],[3461,["इसे आप प्राप्त करिए, आप इसके अधिकारी हैं।"]],[3464,["इस भारत भूमि पे जन्म लेने के लिए अनेक","आपने पुण्य कर्म किए हैं। उसके सिवाए आप","इस धरती पे जन्म नहीं ले सकते हैं।"]],[3471,["और आपने किया क्या है इस देश के लिए?","इसकी जो इतनी बड़ी चीज़ है, उसको पाया नहीं,"]],[3477,["उसको जाना नहीं। उसको जानना चाहिए,","उसको प्राप्त करना चाहिए। एक क्षण में","ये कार्य हो सकता है।"]],[3484,["और इसलिए मैं आपके पास आई हुईं हूँ, कि इसे","आप प्राप्त करें। सब आप ही का है - आपकी","कुण्डलिनी आपकी माँ है।"]],[3492,["वो ही आपकी जन्मदात्री है। आपके आत्मा","आपके अंदर हैं, जो कि परमात्मा का प्रकाश है।"]],[3498,["ये सब आप ही का धन आपको प्राप्त करना है,","हमारा इसमें कोई लेना देना नहीं बनता।"]],[3505,["आशा है फिर बार-बार मेरा आना होगा जयपुर।","यहाँ पर बहुत लोग मैंने देखे कि"]],[3510,["आस्थापूर्वक परमात्मा को पहचानते हैं,","और ये कार्य और भी आगे बढ़ेगा।"]],[3517,["आज भी अगर कोई प्रश्न हो तो पूछिए।","अच्छा रहेगा थोड़ा बहुत प्रश्न पूछ लें"]],[3522,["और उसके बाद इसका हम कार्यक्रम करेंगे, कि","जिससे सब लोग प्राप्त करें उस आत्मा को,","जिसकी बातचीत हुई है।"]],[3532,["साधक: अभी आपने बताया कि आत्मा को हमें","प्राप्त करना चाहिए लेकिन आपने तरीका नहीं","बताया कि आत्मा को प्राप्त कैसे करें?"]],[3538,["श्री माताजी: हाँ, आप तो पक्के साधक हैं। वो ही","तो करने वाले हैं। ठीक है।"]],[3541,["इन्होंने पहले ही ये सवाल पूछ लिया, बड़ा अच्छा","हुआ। ये रियल (सच्चे) साधक की पहचान है"]],[3546,["कि वो ये चाहते हैं कि, 'आत्मा की क्रिया पहले","बताइये। माँ मुझे भूख लगी, मुझे खाने को दो,'"]],[3552,["बस ये असल चीज़ है। बहुत अच्छी","ख़ुशी की बात है।"]],[3556,["साधक: और दूसरी बात है, ये जो चक्र","आपने बताये थे (अस्पष्ट) बताने के लिए,"]],[3559,["इनका क्या फिजिकल एक्सिस्टेंस है वास्तव में","अंदर या हमारी एक कल्पना है कि ऐसी होती है?"]],[3563,["श्री माताजी: नहीं, वास्तविक है बेटा, वास्तविक","है। शारीरिक, मानसिक, भावात्मक"]],[3567,["- वास्तविक, शक्ति है, माने, शक्ति के पुंज","हैं, शक्ति के पुंज हैं।"]],[3573,["साधक: स्थूल रूप है कोई?","श्री माताजी: स्थूल भी रूप है।"]],[3576,["स्थूल रूप है, कि उस जगह में, आपकी जिस जगह","आपका चक्र ख़राब हो जाएगा, आप देखिएगा"]],[3581,["कि आपके जो पीठ के मनके हैं, वो बाहर निकल","आएंगे। स्थूल रूप से भी असर करती है, पर शक्ति","के पुंज हैं, वो शक्ति के पुंज हैं।"]],[3592,["साधक: साढ़े तीन जो कुंडली है","श्री माताजी: हाँ","साधक: ये कहाँ, कौन सी जगह है?"]],[3597,["श्री माताजी: कहाँ?","साधक: साढ़े तीन जैसी ये बता रहे हैं","श्री माताजी: हाँ"]],[3601,["साधक: ये कौन सी जगह है, ये कौन सी","हड्डी के पास है?"]],[3603,["श्री माताजी: वो तो मैं बता रहीं हूँ, सेक्रम बोन","(हड्डी) के अंदर - त्रिकोणाकार अस्थि जो है,","उसके अंदर है।"]],[3609,["ये देखिए नीचे में, यहाँ पर। जो नीचे में पीठ,","रीढ़ की हड्डी के नीचे में एक त्रिकोणाकार","अस्थि है, उसके अंदर।"]],[3617,["साधक: उसके अंदर है?","श्री माताजी: जी हाँ, उसके अंदर ये शक्ति है।"]],[3621,["साधक: जिसमें ये रहता है ये मेरु....","श्री माताजी: मेरुदंड के नीचे"]],[3626,["साधक: अंदर","श्री माताजी: हाँ, मेरुदंड के नीचे ये शक्ति है","पर मेरुदंड वहाँ भी है;"]],[3632,["मेरुदंड की वो दुम है समझ लीजिए","साधक: जहाँ एनस और ये मिलता है?"]],[3638,["श्री माताजी: नहीं, उससे ऊपर। त्रिकोणाकार","अस्थि ऊपर से - उसके ऊपर है।"]],[3643,["साधक: कुण्डलिनी जागरण से पहले","नाड़ी शोधन ज़रूरी है?"]],[3646,["श्री माताजी: नहीं, कोई ज़रूरी नहीं,","कोई ज़रुरत नहीं।"]],[3648,["साधक: कुण्डलिनी जागरण के लिए शक्ति","पात की ज़रुरत है?"]],[3650,["श्री माताजी: नहीं, बिलकुल नहीं है। ये शक्ति पात,","एक नई बीमारी निकल आई है।"]],[3654,["बिलकुल ज़रुरत नहीं। ये तो मैं बहुत ही घबड़ा","गईं हूँ इसको सुन कर के।"]],[3659,["मैंने अभी - आप बैठ जाएँ। इनकी बात बता दें","भैया ये शक्ति पात की बात ज़रूर समझा दें;","मैं तो माँ हूँ न, मुझे बड़ी घबड़ाहट होती है।"]],[3665,["वहाँ पर एक साहब आये। वो मुझे कहने लग गए","कि 'अरुणोदय, बरणोदय' क्या-क्या बताने लग गए"]],[3671,["मैंने कहा ये कहाँ से आया भई? तो कहने लग गए,","\"वो फैलाने हैं, उन्होंने एक किताब लिखी थी कि","उसमें शक्ति पात होना चाहिए।\""]],[3679,["मैंने कहा, 'देखो, तुम जाति के ब्राह्मण हो,' - जाति","के ब्राह्मण थे। 'तुमको एक बात समझनी चाहिए"]],[3685,["कि जो भी ज्ञान है, वो भी उत्क्रांति में पाया गया।","उसकी भी परंपरा होनी चाहिए। ये कहीं बीच","में से ही एक आप निकालिए।"]],[3694,["जैसे रजनीश ने नियो संन्यास निकाला, किसी ने","कुछ और (अस्पष्ट) निकाल दी, इन्होंने एक","और तीसरी निकाल ली।"]],[3699,["इस तरह से आप कोई चीज़ नई नहीं निकाल","सकते।अगर पेड़ में अगर फूल लगने हैं,"]],[3704,["तो वो कायदे से पहले मूल से ऊपर आते हैं,","तब उसमें फूल लगते हैं, जो जीवंत चीज़ है।"]],[3709,["लेकिन ये तो आप इधर से एक उठा के लाते हैं,","शक्ति पात करते हैं, कहीं हाथ में ये लेकर"]],[3714,["- ये सब कहीं शास्त्रों में वर्णित नहीं है - ऐसी","चीज़ हमको माननी ही नहीं चाहिए।"]],[3719,["पर ये अपील करती है इंटेल्लेक्टुअल्स (बुद्धिजीवों)","को क्योंकि कोई नयापन लेकर के आती है।"]],[3725,["नयापन तो होता ही है। आज सहज योग भी एक","नयापन लिए है लेकिन इसका आधार है।"]],[3730,["साधार होनी चाहिए। जब तक इसका आधार","नहीं, इसका कोई अर्थ नहीं लगता।"]],[3736,["साधक: इसमें गुरु की आवश्यकता क्यों पड़ती है?","श्री माताजी: हाँ गुरु की आवश्यकता है, लेकिन माँ","जो है, वो एक प्रकार की गुरु ही समझ लीजिए।"]],[3743,["लेकिन हम अपने को गुरु-वुरु नहीं मानते हैं","क्योंकि जैसे अभी हम आये, तो आपने कहा कि,","\"माँ आप आ गए, तो हम कैसे बैठें?\""]],[3750,["ठीक है आपने कहा। लेकिन कोई माँ के सामने","खड़ा थोड़े ही होता है। माँ है।"]],[3755,["माँ के सर पे भी बैठिए, तो भी माँ है, चाहे","पैर पर भी आइये, तो भी माँ है।"]],[3760,["माँ और गुरु में बड़ा अंतर है, बहुत बड़ा अंतर है।","हम तो देखते हैं कुछ-कुछ गुरुओं को -"]],[3764,["तो वो तो मार हालत खराब है, जो असल हैं।","हालत खराब कर देते हैं एक-एक की।"]],[3769,["साधक: ये (अस्पष्ट) के ऊपर होती है या","(अस्पष्ट) के मुँह में?","श्री माताजी: किसमें?"]],[3773,["शिश्न के ऊपर। हाँ, ये पॉइंट आपने ठीक कहा","है, ये पॉइंट ठीक कहा है।"]],[3778,["बहुत ज़रूरी चीज़ है, इसको मैं समझा दूँ।","तो समझ गए न आप? तो वो नहीं। आपकी","बात ज़रूर है ये बड़ा कनफ्यूशन है।"]],[3784,["कि ऊपर है या नीचे है - ऊपर है। नीचे में जो है,","वहाँ पर मूलाधार चक्र है, जिसमें गणेश जी","बैठे हुए हैं।"]],[3792,["ऊपर में गौरी का स्थान है जो कन्या का है।","ये बड़ी गड़बड़ कर दी है लोगों ने"]],[3798,["क्योंकि, हो सकता है माँ स्वरुप होने की वजह से,","हम ऐसा एकदम नहीं कहेंगे, कि इतने","महादुष्ट ही रहे होंगे"]],[3804,["लेकिन गलत फहमी में, इन्होंने गणेशजी को सूँड़","को समझा होएगा कि ये कुण्डलिनी, क्योंकि","बाह्य से देखा, अंदर से तो गए नहीं।"]],[3811,["लेकिन ये तो शुद्ध विद्या है, शुद्ध कन्या है,","जो गौरीजी हैं बैठीं हुईं हैं।"]],[3819,["और उसके नीचे गणेशजी अपनी माँ की रक्षा के","लिए बैठे हैं, लेकिन तांत्रिक लोगों ने इसको","शिश्न से बना दिया"]],[3827,["और जब आप - आप सोचें कि माँ को किस लेवल","पे ले आये। आप सोचिये, आप हिंदुस्तानी हैं।"]],[3835,["ये तो फ्रायड की थ्योरी हो गई। माँ को इस लेवल","पे ले आये और तब ये धंधे करते हैं,","क्योंकि व्यभिचार है।"]],[3844,["व्यभिचार करने से देवी उठ जाएगी और चाहे जो","करो। यही तांत्रिकों ने कमाल करके रखी है"]],[3852,["कि त्रिकोणाकार अस्थि के नीचे में गणेशजी बैठे हैं","और अपनी माँ की लज्जा रक्षण कर रहे हैं।"]],[3857,["वो छोड़ कर के उसको शिश्न पे बिठा दिया","तो हो गया - आपने माँ को कहाँ बिठाया?"]],[3865,["हिंदुस्तान में ऐसा आदमी मुश्किल से मिलेगा","जो माँ की पवित्रता नहीं जानता है।"]],[3871,["साधक: मैं जालंधर गया था, (अस्पष्ट) वो गुरूजी हैं,","जालंधर में"]],[3878,["श्री माताजी: यही सब सिखाते हैं, शिश्न में","बैठी हुई है? यही तो सब है।"]],[3883,["साधक: एक बात और है साहब कि हम कुछ यहाँ","पर थोड़े से व्यक्ति पढ़े लिखे हैं। मैगज़ीन, बुक्स","वगैरा हम थोड़े से लोग पढ़ते हैं।"]],[3889,["आज कल हमारे भारत देश के अंदर जहाँ पर","80% लोग ए बी सी डी ऍफ़ नहीं जानते,"]],[3894,["सुबह से शाम तक काम करके अपने जीवन","80 साल, 70 साल गुज़ार देते हैं,"]],[3898,["तो इसका क्या अर्थ हुआ, कि उन लोगों का","जीवन बिलकुल व्यर्थ गया?"]],[3901,["श्री माताजी: नहीं, नहीं बिलकुल भी नहीं।","साधक: उसपर आपके क्या कमैंट्स हैं?"]],[3904,["श्री माताजी: नहीं, नहीं वो तो सभी, ज़्यादातर वो","सहज योग में आते हैं, बनिस्बत इसके कि","जिन लोगों के पास समय है।"]],[3909,["जिनके पास समय वो तो क्लबों में रहते हैं।","जिनके पास समय नहीं है, वही आते हैं।"]],[3914,["लेकिन सहज योग की एक विशेषता ये है, कि जब","आप इसको प्राप्त करते हैं - जैसे हम देहातों में","ज़्यादातर बेटे काम करते हैं शहरों में कम -"]],[3924,["और देहात में जब लोग आते हैं, पार हो जाते हैं,","एक तो उनकी गन्दी आदतें सब छूट जातीं हैं"]],[3929,["सब उनके व्यसन छूट जाते हैं, और इतना आदमी","डायनैमिक हो जाता है कुछ पूछिए नहीं।"]],[3934,["एक बार ऐसे ही जा रहे थे खेती में; देखा","एक खेत बड़ा लहलहा रहा था।"]],[3938,["हमने कहा, 'ये किसका खेत है?'","तो कहने लगे, 'एक सहज योगी का।'"]],[3941,["मैंने कहा, \"अच्छा, क्या किया?\" कहने लगे, \"कुछ","नहीं माँ, इसमें मैंने चरणामृत थोड़ा डाल दिया था"]],[3946,["मेरे इसमें, उसके वाई विब्रेशन्स से ही","यह इतना लहलहा गया।"]],[3952,["तो एक ऑस्ट्रिया के हमारे सहज योगी था;","मैंने उससे कहा कि, \"अच्छा, तुम इसपर","एक्सपेरिमेंटेशन (प्रयोग) करो।\""]],[3956,["उसने एक्सपेरिमेंट किया, वो इतना हैरान हो गया,","कि जब उसने पानी, सादा पानी दिया तो"]],[3964,["- मेज़ (मक्का) पर उसने किया था - जिसको भुट्टा","कहते हैं; भुट्टे का पेड़ इतना ऊँचा था"]],[3969,["जिस वक़्त उन्होंने विब्रेटेड पानी से किया","इतना ऊँचा - उसके उसने फोटो बनाये।"]],[3973,["और ये बड़ा भारी एक साइंटिस्ट है,","जो कि यू.एन. में एम्प्लॉयड है।"]],[3978,["और उसने उसपर पेपर लिखा हुआ है;","अभी हम गवर्नमेंट ऑफ़ इंडिया (भारत सरकार)","को हम भेजने वाले हैं।"]],[3981,["पर वहाँ किसके पूछने वाला है, कौन देखने","वाला है। उनके टाइम ही नहीं। सबको","दूसरी बीमारियाँ हैं।"]],[3986,["यहाँ तो किसी को टाइम ही नहीं है न। जो लोग","पूरे दिन काम करते हैं, उनको टाइम है","भगवान के लिए।"]],[3994,["साधक: कहा जाता है, कि जो व्यक्ति अपनी रोटी","चौबीस घंटे में से कम समय में कमा लेता है, उसी","के दिमाग में ये अधिकतर बातें आतीं हैं"]],[4001,["श्री माताजी : खुराफ़ाती!","साधक: कि ईश्वर क्या है, भगवान क्या है ?","श्री माताजी: नहीं, नहीं, उनके कम आती हैं।"]],[4004,["साधक: जो व्यक्ति सुबह से शाम तक अपनी","मेहनत करता है","श्री माताजी: उसको ज़्यादा आती है, बेटे"]],[4009,["साधक: सामने काम को रखते हुए और","किसी बात का ध्यान नहीं करता है।"]],[4011,["इस (अस्पष्ट) उस व्यक्ति के जीवन अपने आप","मोक्ष किसी ऊपर की शक्ति से"]],[4016,["वो अपने पुनर्जन्म की (अस्पष्ट) से बच जाता है","- क्या ऐसा माना गया है?"]],[4020,["श्री माताजी: नहीं, नहीं ऐसा नहीं है। जो लोग बहुत","काम करते हैं, जिसको आप कह रहे हैं,"]],[4023,["वर्कोहॉलिक जिसे कहते हैं - उनकी बात","तो नहीं कर रहे हैं आप?"]],[4026,["साधक: नहीं सर जो लोग देहात","श्री माताजी: नहीं - मतलब देहात में जो लोग हैं"]],[4029,["साधक: जी हाँ","श्री माताजी: देहात के लोगों की बात।","अपना देश तो देहात में रहता है।"]],[4033,["हाँ, तो देहात के लोग जो हैं, वो तो बहुत","आसानी से पार हो जाते हैं और होने के बाद","डायनैमिक(गतिशील) हो जाते हैं।"]],[4039,["लेकिन जो शहरों में वर्क ऐलकोहॉलिक्स हैं,","उनका इलाज तो कोई भी नहीं कर सकता","- वो भी नहीं कर सकते, वो तो बेकार हैं।"]],[4046,["लेकिन दूसरे, जो कि, जिनके पास फुर्सत ज़रुरत से","ज़्यादा है, जैसे जो घडी बाँध कर के हमेशा घूमते हैं"]],[4052,["उनसे पूछिए कि, \"मुझे लंदन जाने का है।\"","\"भई क्यों, इतनी मारामार क्यों?\" \"मुझे वहाँ","जाकर बॉल अटैंड करने का है।\""]],[4059,["आधा टाइम - आप सोच लीजिए - हम लोग -","अब हमारी उमर, अब चौसठवाँ साल हमारा चल","रहा है; हमने ज़िन्दगी काफ़ी देख ली।"]],[4067,["पहले न तो इतनी पार्टियाँ होतीं थीं, न कुछ","होता था - असली दोस्ती रहती थी।"]],[4071,["आजकल रोज़ ही पार्टी। इसके घर ख़ाना ख़ाने","जाओ, उसके घर ख़ाना ख़ाने जाओ। लंदन में तो","पाँच-पाँच रिसैप्शन्स अटैंड करने पड़ते हैं।"]],[4078,["टाइम बर्बाद करने का पूरा इंतज़ाम करने के बाद,","हम क्या कहें, कि हमारे पास टाइम नहीं है।"]],[4083,["टाइम तो बहुत ज़्यादा हो गया है, क्योंकि सब चीज़ें","सहूलियत से मिलने लग गईं। आपके सब चीज़ें","इतनी सहूलियत हो गई -"]],[4090,["आपका खाना आसानी से पकने लग गया है,","आपको चीज़ें इतनी सहूलियत से मिलतीं हैं, लेकिन","बर्बाद करने का इंतज़ाम भी बहुत हो गया है।"]],[4097,["हम इतना टाइम बर्बाद करते हैं सुबह से","शाम तक जिसकी कोई हद्द नहीं है।"]],[4101,["पर अगर कोई सोचे कि थोड़ा सा समय परमात्मा","के लिए देना है, तो इत्ते से एक क्षण में भी,"]],[4107,["परमात्मा आपके साथ हो सकते हैं।","आप बोलिए।"]],[4111,["साधक: माँ सेक्स के द्वारा बच्चों को जन्म","देती है"]],[4115,["श्री माताजी: ऐ?","साधक: माँ सेक्स के द्वारा ही बच्चों को जन्म","देती है, यह तो कहा जा सकता है, लेकिन आपने","कुछ ऐसे कहा जैसे अवांछनीय हो"]],[4123,["श्री माताजी: माँ सेक्स से जन्म देती है - ये तो गलत","स्टेटमेंट हुआ बेटा। स्टेटमेंट गलत हो गया,","स्टेटमेंट गलत है।"]],[4130,["साधक: अस्तित्व तो है ही। (अस्पष्ट)","श्री माताजी: नहीं, नहीं सेक्स बुरी बात तो","मैंने नहीं कही, मैंने नहीं कही।"]],[4136,["लेकिन पत्नी के साथ सेक्स होता है, माँ के","साथ तो नहीं।"]],[4140,["साधक: बच्चे को जन्म देती है।","श्री माताजी: हाँ, बच्चों को जन्म देना","सेक्स का काम नहीं है।"]],[4143,["बच्चे को जन्म देना सेक्स का काम नहीं है।","सेक्स तो पति-पत्नी में होता है ना, बच्चे से तो","नहीं होता। बच्चे से तो पवित्र रिश्ता है।"]],[4152,["साधक: माँ भी पत्नी होती है","श्री माताजी: हैं?"]],[4154,["साधक: माँ भी पत्नी होती है","श्री माताजी: पत्नी होती है, लेकिन पवित्र रिश्ता है।","माँ से तो पवित्रता है, ये तो मानना चाहिए।"]],[4159,["साधक: कुंडलिनी जागरण द्वारा क्या","अंदरूनी गर्मी बढ़ गई होती है (अस्पष्ट)"]],[4166,["श्री माताजी: कुछ नहीं, बिलकुल नहीं होता।","ये तो गलत लोगों के पास जाइए"]],[4169,["जो कि माँ से ही खेलते हैं, उनको होता है।","जो गलत काम करते हैं उनसे ही होता है।"]],[4175,["जो इस तरह की चीज़ें करते हैं, जिनका चरित्र","स्वयं ठीक नहीं है, उनसे होता है।"]],[4180,["वो लोग, ऐसे लोगों के पास जाने से न जाने","क्या-क्या - एक साहब के तो पूरे यहाँ से","यहाँ मैंने ब्लिस्टर देखे।"]],[4185,["वो कहने लगे, 'मेरी कुंडलिनी जागृत हुई।'","दूसरे साहब पागल जैसे दौड़ रहे थे।"]],[4189,["मैंने कहा, 'क्या हुआ?' कहने लगे,","'मेरी कुंडलिनी जागृत हो गई।'"]],[4192,["मैंने कहा, \"ये कैसे?\" कहने लगे, \"बस जैसे","कोई बर्रिया मुझे काट रही है;"]],[4196,["सब बर्रिया मेरे बदन में काट रहीं हैं।","और सारी दुनिया भर में पागल जैसे घूम रहे थे।"]],[4200,["मैंने कहा, \"ये किसके पास गए?\" कहने लगे,","\"वो फलाने साहब थे, तो उन्होंने मेरी कुंडलिनी","जागृत की।\""]],[4204,["तो मैंने कहा,\" उनकी हुई थी?\" कहने लगे,","\"उनकी भी ऐसी ही हुई थी।\""]],[4206,["मैंने कहा, \"अच्छा! तो फिर तुम क्यों गए उसके","पास?\" जब उनकी ऐसी कुंडलिनी जागृत हुई थी,","तो वो तुम्हारी भी ऐसी ही करेगा।"]],[4213,["भई जब सामने का आदमी ऐसा हो रहा है,","तो तुम काहे उसके पास गए? लेकिन","इंसान बड़ा अजीब है।"]],[4218,["शराबखाने से आदमी आता है, गिरता है उसके","सामने, और ये उसको लांघ कर आगे चला","जाता है। इंसान की बुद्धि का क्या कहें?"]],[4225,["साधक: वैसे ये कुछ ऐसे ही वो होते हैं, जैसे","ततैया काट रही है, जैसा ऐसा कुछ साधना","की तरफ जाता है आदमी।"]],[4232,["श्री माताजी: हाँ, गलत चीज़ की तरफ जाइए तो","होगा ही। अगर मर्यादा आप लाँघिये तो होगा ही।"]],[4237,["तो होता है ना ये। सब दुनिया भर की चीज़ें होतीं हैं,","पर वो तो गलत चीज़ है न। गलत चीज़ से आप"]],[4242,["साधक: (अस्पष्ट) नहीं है क्या कि कुंडलिनी","जागृत हो रही है, अगर ऐसा कुछ हो रहा है,"]],[4246,["ये बर्रिया काटने जैसी स्तिथि आती है, तो ये","क्या उसका कोई पहचान है कि, 'हाँ, ये जागृत'"]],[4252,["श्री माताजी: नहीं, नहीं, नहीं, बिलकुल नहीं। उसकी","पहचान एक ये है कि आपके सर में से, यहाँ","तालु में से ठंडी-ठंडी हवा आती है"]],[4257,["हाथ में ठंडी-ठंडी हवा - ये इसकी पहचान है।","चारों तरफ इसकी ठंडी-ठंडी - 'सलीलम,","सलीलम' वर्णन है।"]],[4265,["'सलीलम, सलीलम' चारों तरफ ठंडा-ठंडा","सा लगता है।","साधक: ऐसा ऐसा कोई नहीं शरीर में","दर्द पैदा होती हो?"]],[4271,["श्री माताजी: नहीं, नहीं कुछ नहीं, दर्द-वर्द कैसे,","ये आपकी माँ है। वो सारा"]],[4274,["साधक: दर्द नहीं, जैसे ये कम्पन, कम्पन","पैदा होता हो?"]],[4276,["श्री माताजी: नहीं, होना नहीं चाहिए। अगर कोई","गलत चीज़ हो अंदर, तो थोड़ा कम्पन हो जा","सकता है। थोड़ा बहुत होता है।"]],[4282,["अगर कोई अंदर गलत चीज़ हो अंदर, उसको","सही करने में थोड़ा बहुत होता है कम्पन, लेकिन","ऐसा कोई दुखदाई नहीं होता है।"]],[4288,["साधक: ये कुंडलिनी जागृत जो होती है, वो कुछ","समय के लिए होती है, कुछ परमानेंट टाइम","के लिए होती है?"]],[4292,["श्री माताजी: परमानेंट बेटे।","साधक: (अस्पष्ट)","श्री माताजी: हाँ, और क्या।"]],[4297,["साधक: इसका अनुष्ठान क्या है?","साधक: तरकीब इसकी?"]],[4302,["श्री माताजी: वही तो, तरकीब ही तो बताने आये हैं।","तरकीब","साधक: (आपस में वार्तालाप)"]],[4305,["साधक: तो जाने वो जब कुछ होगा तब मालूम पड़ेगा।","पहले इसका शुरुआत कैसे किया था (अस्पष्ट)"]],[4312,["श्री माताजी: आपको यही बताना है, पहले","इनके सवालात तो हो जाने दीजिए।"]],[4315,["आप ठीक कह रहे हैं। बिलकुल आप सही हैं।"]],[4318,["साधक: हम तो स्कूल में पहले जा कर के बैठे,","तो कक्का श्री राम जी हम तो लिखना चाहते हैं","पहले - ये तो बड़ी बड़ी बातें हैं।"]],[4325,["श्री माताजी: बड़ी बात - वो बड़ी बात काहे","करने की, सही बात कह रहे हैं।"]],[4328,["भई अगर आपको दिया जलाना है तो बताइये,","बटन कहाँ है, ठीक करो।"]],[4332,["बाद में सीखते रहेंगे कहाँ से लाइट आई,","क्या हुआ। ठीक बात कह रहे हैं आप।"]],[4336,["आप बहुत सही आदमी हैं। यही है, यही जो मैं","कहती हूँ कि हिंदुस्तान के देहातों में ये चीज़ है।"]],[4342,["साधक: अब इसका बड़ा प्रूफ ये होगा सब से, कि","जिस समय ये अनुभूति आएगी, इसमें कोई","संदेह नहीं रहेगा।"]],[4347,["श्री माताजी: हाँ!","साधक: मस्तिष्क या दिमाग अपने आप","कहेगा कि ये हो गया।"]],[4351,["श्री माताजी: बस। और आप अपना सर्टिफिकेट","दीजिए, हमें नहीं देने का है।"]],[4354,["बस सीधी बात। अभी आपके यहाँ ऐसे बहुत","से लोग हैं, जिनको अनुभूति आ गई है।"]],[4358,["लेकिन अभी आपको नहीं आई। और सही बात है","कि अनुभव शून्य की बात क्या की जाए?"]],[4364,["ये तो सब अनुभव शून्य बात है - तो अनुभव को","पाएं। जैसे आपने कहा ये तो बुज़ुर्ग हैं और","समझदार आदमी हैं।"]],[4370,["ये समझदारी की बात है, बिलकुल समझदारी","की बात है।"]],[4374,["साधक: आपके विषय में पढ़ा था कि आप","छूकर ये एहसास करा सकते हैं।"]],[4378,["श्री माताजी: अरे बेटे, उसकी ज़रुरत नहीं। वो किसी","को किया होगा छू-छा के, तो उन्होंने लिख दिया","होयेगा लेकिन छूने की कोई ज़रुरत नहीं"]],[4384,["साधक: कई वर्ष पहले बहुत अरसा हो गया","पढ़ा था कहीं, पाँच, सात, दस, बारह साल पहले।"]],[4388,["श्री माताजी: हाँ कोई कठिन जीव होएंगे, तो उनको","छूना भी पड़ा होगा। क्या करें, कभी-कभी","तो हाथ तोड़ने पड़ते हैं।"]],[4394,["साधक: कुंडलिनी शक्ति जागृत करने के लिए,","कोई अवस्था भी ज़रूरी है (अस्पष्ट)"]],[4397,["श्री माताजी: हाँ?","साधक: कुंडलिनी शक्ति जागृत करने के लिए,","अवस्था चाहिए होगी?"]],[4400,["श्री माताजी: नहीं, कोई नहीं कोई नहीं","साधक: क्योंकि बचपन में या किसी","विशेष जीवन में (अस्पष्ट)"]],[4404,["श्री माताजी: कोई नहीं बेटे","साधक: बच्चे को भी?"]],[4406,["श्री माताजी: सबकी। बच्चों की तो सबसे पहले","होती है। अच्छा अब ये साहब एक और कह","रहे हैं कुछ नहीं तो इनकी बात ..."]],[4416,["बात ये है ना कि जिस वक़्त जागृति शुरू होगी","तब आप ढूंढेंगे और कोई सवाल -"]],[4420,["ये नहीं पूछा, वो नहीं पूछा, इसलिए पहले आपको","सैटिसफाइड (संतुष्ट) कर दें। हाँ फरमाइए।"]],[4424,["साधक: कुण्डलिनी और आत्मा में (अस्पष्ट)","क्या होता है","श्री माताजी: क्या कह रहे हैं?"]],[4427,["सहज योगी: कुण्डलिनी और आत्मा में","सम्बन्ध क्या है?"]],[4430,["श्री माताजी: कुण्डलिनी जो है, ये आदिशक्ति है;","आदिशक्ति का हमारे अंदर प्रतिबिम्ब है।"]],[4436,["और आदिशक्ति जो है, ये परमात्मा की शक्ति है।","और परमात्मा का प्रतिबिम्ब हमारे अंदर आत्मा है।"]],[4442,["समझ गए? परमात्मा की जो शक्ति है, वो","आदिशक्ति। सदाशिव की शक्ति को आदिशक्ति","कहते हैं - परमात्मा की शक्ति।"]],[4450,["साधक: (अस्पष्ट)","श्री माताजी: क्या कह रहे हैं?"]],[4453,["सहज योगी: आत्मा की तलाश और कुण्डलिनी","की तलाश एक ही बात है?"]],[4457,["श्री माताजी: कुण्डलिनी की तलाश क्या करने","की है? उसकी जागृति करने की है"]],[4460,["और वो ही खोज के, आपकी आत्मा लाकर के,","आपके अंदर जागृत कर देती है।"]],[4465,["उसकी तलाश करने की ज़रुरत नहीं।","किसी चीज़ की तलाश नहीं।"]],[4469,["साधक: जैसे कुण्डलिनी जागृत (अस्पष्ट)","श्री माताजी: कुण्डलिनी?"]],[4476,["साधक: जैसे कुण्डलिनी आगे से चोट करने लगे","श्री माताजी: हाँ?"]],[4479,["साधक: तो रास्ते के चक्र तो अछूते नहीं रहते होंगे?","श्री माताजी: रास्ते के?"]],[4482,["सहज योगी: कुण्डलिनी आज्ञा चक्र पे चोट","करने लगे, तो जो रास्ते के चक्र हैं","साधक: वो अछूते नहीं रहते होंगे"]],[4488,["श्री माताजी: सब खोलने पड़ते हैं। आज्ञा अगर","आपका पकड़ा है, तो उसको खोलेंगे।"]],[4492,["देखते हैं, कहाँ है कुण्डलिनी; सब खोलने","का काम तो करने का है, वही तो काम है।"]],[4496,["साधक: डायरेक्ट आज्ञा चक्र पे पहुँचा","जा सकता है?"]],[4502,["श्री माताजी: डायरेक्ट आपके सहस्त्रार पे पहुँचाएँगे;","आज्ञा चक्र क्या बात है।"]],[4506,["साधक: रास्ते के सब चक्र क्लियर होंगे","तभी तो ऐसा होगा (अस्पष्ट)"]],[4510,["श्री माताजी: हैं?","साधक: रास्ते में जो चक्र हैं"]],[4512,["श्री माताजी: सारे उसमें से सबका वो षट चक्र छेदन","करती हुई तत्क्षण यहाँ से निकल आएगी।"]],[4517,["साधक: ऐसा नहीं होगा सीधा ही","आज्ञा चक्र पे पहुँच जाए?"]],[4519,["श्री माताजी: नहीं, नहीं, यहाँ से निकलेगी","साहब - तालु से, ब्रह्मरंध्र से"]],[4525,["ब्रह्मरंध्र से निकलेगी, तालु को छेदती है,","वो षट चक्र भेदन करती है -"]],[4529,["आज्ञा चक्र पे नहीं रुकती है, ये तो खिड़की है","सिर्फ, यहाँ से बाहर निकल आती है।"]],[4533,["अच्छा बेटे, बैठो। कुछ तो जानते ...","साधक: अगर बहार निकल गई तो सभी","चक्र सही समझो","श्री माताजी : हाँ"]],[4542,["ये बैठे हैं दो चार, इनकी निकल","आई है, इनसे तो पूछ लीजिए।"]],[4545,["साधक: ये क्रिया करने में किसी का मतलब","जो है डीइक्विलिब्रियम भी हो सकता है?","श्री माताजी: क्या नहीं होता है?"]],[4550,["सहज योगी: डीइक्विलिब्रियम","श्री माताजी: अरे नहीं साहब आप सुकृत हो","जाते हैं - विकृत क्या होएँगे?"]],[4556,["साधक: कोई ज़रूरी थोड़ा है कि हर आदमी जो है","उसको रिअलिज़शन (आत्मसाक्षात्कार) करते ही","अपने आपको इक्विलिब्रियम में स्थित कर सके?"]],[4562,["श्री माताजी: क्यों नहीं?","साधक: कोई आदमी ऐसा होता है कि जो उसको","प्राप्त नहीं कर पाए और अपने आपको विकृत करे"]],[4566,["श्री माताजी: विकृत हो जाए? ये कैसे होगा?","साधक: वो आपसे पूछ रहा मैं।"]],[4570,["श्री माताजी: आप तो ऐसी बात कर रहे हैं।","जैसे समझ लीजिए आपने बीज को बोया।"]],[4575,["तो वो क्या बीज जब वो जब अंकुरित होता है,","तो वो विकृत कैसे होगा?"]],[4579,["साधक: बीज तो कई उगते भी नहीं साहब।","श्री माताजी: नहीं, उगते तो नहीं। वैसा तो है ही।"]],[4582,["कुछ लोग तो पार नहीं होते; ये तो बात सही है।","नहीं होते - चलो मेहनत करेंगे।"]],[4586,["आज नहीं होंगे, कल हो जाएंगे; कल नहीं","होंगे परसों होएंगे। हम तो मेहनत के लिए","बैठे हुए हैं।"]],[4591,["उसमें घबड़ाने की कौन सी बात है।","आप ज़रुरत से ज़्यादा घबड़ा रहे हैं।"]],[4596,["आप पार हो जाइएगा। बस पहले पार हो जाओ।","अब बस। अच्छा बोलो क्या बात है?"]],[4600,["साधक: जागृति का तरीका।","श्री माताजी: क्या कह रहे हैं?","सहज योगी: जागृति का तरीका है?"]],[4606,["श्री माताजी: वही तो बता रहे हैं। अभी उसके","लिए तो समय ही नहीं दे रहे हैं। पहले","इधर-उधर की बात कर रहे हैं।"]],[4611,["अच्छा चलिए। बस वही बात ठीक है। जो","बात आप कह रहे हैं सही कह रहे हैं,"]],[4618,["कि पहले जागृति होनी चाहिए, और कुछ नहीं","चाहिए; ये तो सही बात कह रहे।"]],[4623,["यही तो चीज़ है। हाँ, अच्छा कुछ लोग सामने","बैठ जाएं, आराम से।"]],[4635,["साधक: बिलकुल आज़ादी में।","श्री माताजी: कोई घबराने की चीज़ नहीं है।"]],[4639,["कोई परेशानी की चीज़ नहीं है। इसमें किसी","को कोई तकलीफ नहीं होगी। आप सामने","बैठिये, बैठिये इधर।"]],[4644,["आपको तो ज़रूर पार कराना है मुझे। बैठिये इधर।","आइये। पीछे ज़रा कुर्सियाँ खींच लीजिए।"]],[4655,["जितने आगे बैठना है बैठें, नहीं बैठना है,","जैसे बैठ सकते हैं, बैठ जाइये।"]],[4659,["ऐसी कोई बात नहीं है। पर जहाँ तक हो सके","आगे की तरफ आ जाएं, तो अच्छा रहेगा।"]],[4663,["साधक: आगे की कुर्सी में आ जाएं जो लोग पीछे हैं।"]],[4670,["श्री माताजी: अब जैसे हम कहेंगे, वो आप करिए,","क्योंकि आप ही अपनी कुण्डलिनी जागृत करेंगे"]],[4675,["हम तो नहीं करने वाले, सीधा हिसाब है।","और कैसे करना है, वो हम समझा देंगे।"]],[4680,["लेफ्ट हैंड आप हमारी ओर करिए। आराम से।","अपने गोद में, अपने गोद में, लेफ्ट।"]],[4689,["हम इसलिए लेफ्ट, राइट कहते हैं, क्योंकि","कोई इसको सीधा हाथ, उल्टा हाथ ऐसे कहते हैं।"]],[4694,["कोई कुछ कहते हैं। हिंदी भाषा में, हर प्रोविंस","(प्रांत) में अलग-अलग कहा जाता है।"]],[4698,["इसलिए हम लेफ्ट और राइट ही कहें। या तो","उल्टा हाथ, उल्टा हाथ हमारी ओर करें।","सीधा, इस तरह से।"]],[4706,["साधक: कितना आगे करें?","श्री माताजी: बस अपने गोद में आराम से,","आराम से बैठो। सब आराम से प्राप्त होगा।"]],[4712,["सहज का मतलब है, आप ही के साथ जन्म हुआ है","- सहज। बस ऐसे आराम से, आराम से।"]],[4718,["और राइट हैंड जो है, इसको हम इस्तेमाल करेंगे,","क्योंकि ये जो है, ये इच्छा शक्ति है, और ये जो है,","ये क्रिया शक्ति है।"]],[4728,["इसको हम इस्तेमाल करेंगे और अलग-अलग","चक्रों पे लगाएंगे। किस प्रकार, वो हम","आपको दिखाते हैं।"]],[4733,["बड़ा ही आसान है। सबसे पहले हमारे ह्रदय पे","हम रखेंगे। उसके बाद हम पेट के ऊपर के","हिस्से में रखेंगे।"]],[4742,["ये क्या चक्र है, मैं बताऊँगी खुदी। इसके बाद पेट","के नीचे के हिस्से में रखेंगे। उसके बाद फिर वापस","पेट के ऊपर के हिस्से में रखेंगे।"]],[4750,["सब लेफ्ट हैंड साइड पे काम होगा। सब लोग","करें, मेहरबानी से। अभी अगर नहीं हुआ,","तो बाद में कहेंगे, नहीं हुआ।"]],[4756,["उसके बाद में ह्रदय पे रखेंगे। फिर यहाँ पर,","विशुद्धि चक्र पे, इस जगह में सामने से,","इस तरह से हाथ पकड़ के रखेंगे।"]],[4765,["उसके बाद माथे पर यहाँ इस तरह से आड़ा यूँ","पकड़ेंगे, उसको दबाएंगे। पीछे में यहाँ पर,","ऐसे रखेंगे।"]],[4774,["उसके बाद सर पे, ये जो तलुआ है, इसको बराबर","तालु स्थान पे रखके, दबाके और सात बार घुमाएंगे।"]],[4783,["दबाके यूँ, ऐसी उँगलियाँ करके। बस,","इसके बाद काम हो जायेगा।"]],[4789,["साधक: घुमायें कैसे?","श्री माताजी: इसको ऐसे रखिए, दबाइये","और घुमाइए।"]],[4793,["ना, ना, ना, ना। अपने हाथ को ऐसे-ऐसे घुमाइए,","दबाकर। ऐसे यूँ, जैसे मैं घुमा रही हूँ, ऐसे। ठीक है।"]],[4801,["ये नहीं भी करो तो भी हो जायेगा - आप लोग बड़े","साधु-संत हैं। कोई ज़रुरत नहीं परेशान होने की।"]],[4808,["पहले लेफ्ट हैंड मेरी ओर करें और","राइट हैंड ज़मीन पर रखें।"]],[4813,["अब ये मैंने कहा था, कि आप योग भूमि में बैठे हो,","इसलिए इस माँ का आशीर्वाद लेना है।"]],[4822,["लेफ्ट हैंड आपने ज़मीन पर कर दिया। हो सकता","है अभी किसी के हाथ में ठंडक आने लग जाये।"]],[4834,["अब राइट हैंड मेरी ओर करें, संतुलन के लिए","और लेफ्ट हैंड इस तरह से।"]],[4840,["राइट हैंड मेरी तरफ - ये सिर्फ संतुलन के लिए।","चश्मे भी उतार दीजिए क्योंकि आँख अब","पूरी समय अब बन्द करनी होगी।"]],[4862,["अब, अब लेफ्ट हैंड मेरी ओर करें। अब आँख बंद","कर लें। लेफ्ट हैंड मेरी ओर और आँख बंद कर लें।"]],[4870,["इसके बाद आँख न खोलियेगा। जब तक मैं नहीं","कहूँगी, आँख न खोलें क्योंकि ये अंतर्योग है।"]],[4874,["सब लोग करें कृपया। कोई देखने के लिए न बैठे।","सब को करना चाहिए - यहाँ देखने के","लिए न बैठें।"]],[4880,["जिनको देखने के लिए बैठना है, उनसे हाथ","जोड़ना है, कि आप लोग तशरीफ़ ले जाएँ।"]],[4885,["यहाँ देखने का कुछ नहीं है; आप मेहरबानी","से तशरीफ़ लेते जाइए।"]],[4889,["यहाँ जिनको ध्यान करना है, वही बैठें,","क्योंकि दूसरे लोग डिस्टर्ब हो जाते हैं।"]],[4894,["इसलिए कृपया सब लोग ध्यान में रहें, कृपया।","नहीं, मेहरबानी करिए;"]],[4899,["साधक: सर के ऊपर हाथ रख लें?","श्री माताजी: नहीं, लेफ्ट हैंड इस तरह।"]],[4902,["मेहरबानी करिए - कोई ज़बरदस्ती करने की","ज़रुरत नहीं। अगर आपको ध्यान नहीं करने","का है, तो आप लोग चले जाइए।"]],[4908,["साधक: आप ना पांच मिनिट रुक जाइए","श्री माताजी: ऐं?","साधक: पांच मिनिट रुक जाइए।"]],[4912,["श्री माताजी: क्यों क्या बात है?","साधक: वो बाहर गए हैं ज़रा आ जाएं (अस्पष्ट)।","श्री माताजी: ऐं?"]],[4916,["साधक: इनके हस्बैंड बाहर गए हैं।","साधक: बाहर गए हैं, ज़रा आ जाते।","साधक: यूरिनल के लिए गए होंगे शायद।"]],[4920,["श्री माताजी: अच्छा ठहरते हैं। कोई बात नहीं। आने","दीजिए। वो जब भी आएंगे हो जायेगा, अच्छा।","घबड़ाये नहीं। देखिए, ये आतुरता देखिए।"]],[4928,["ये सादगी देखिए, ये सादगी देखिए। इस सादगी पर","जब तक मनुष्य नहीं आता, तब तक उसके साथ","कुछ नहीं हो सकता है।"]],[4935,["जो लोग सादगी में नहीं रहते हैं, वो लोग ज़िन्दगी","की सारी परेशानियों में फँस जाते हैं।"]],[4939,["कैंसर की बीमारी, इसकी बीमारी, उसकी बीमारी -","सारी चीज़ें उससे पड़ जातीं हैं।"]],[4945,["अच्छा, अब कोई हाथ नहीं। अब लेफ्ट हैंड मेरी","ओर रखें - इस तरह से रखें लेफ्ट हैंड।","अब राइट हैंड ह्रदय पे रखें।"]],[4953,["आँख बंद करें। ह्रदय में आपके आत्मा का वास है,","इसलिए एक सवाल मुझसे आप पूछें तीन बार -"]],[4967,["पूर्ण विश्वास के साथ, \"माँ, क्या मैं आत्मा हूँ?\";","मन में पूछिए, \"माँ, क्या मैं आत्मा हूँ?\" मन में पूछें पूर्ण ह्रदय से।"]],[4996,["अपने में पूरा विश्वास रखना चाहिए।"]],[5001,["अब इसी सीधे हाथ को, राइट हैंड को आप, लेफ्ट","साइड में ही, पेट के ऊपर के हिस्से में रखें।"]],[5016,["ये गुरु तत्व का चक्र है। क्योंकि आप आत्मा हैं,","आप अपने गुरु हो जाते हैं। इसलिए दूसरा सवाल","इसी सिलसिले में आप पूछिए,"]],[5026,["\"माँ, क्या मैं स्वयं का गुरु हूँ?\"- ये आप तीन मर्तबा","पूछिए। ये बड़े मूल भूत प्रश्न आप मुझसे पूछ रहे हैं।"]],[5041,["\"'क्या मैं स्वयं का गुरु हूँ? माँ,","क्या मैं स्वयं का गुरु हूँ?\""]],[5064,["आप क्यों नहीं कर रहे भाईसाहब?"]],[5071,["कर लीजिए, फायदा होगा। लेफ्ट हैंड मेरी ओर","करिए और राइट हैंड पेट पे रखिए।"]],[5078,["लेफ्ट हैंड साइड में, प्लीज। पूछिए सवाल तीन बार।","अब इस राइट हैंड को - आँख बंद रखें और चश्मा","उतार लें क्योंकि आँख पे अच्छा असर आएगा।"]],[5097,["अब इस राइट हैंड को आप पेट के नीचे के हिस्से","में रखें। अब एक बात जान लीजिए कि","प्रसन्नचित्त होना चाहिए।"]],[5107,["आपको परमात्मा के दरबार में उतरना है,","आप प्रन्नचित्त रहें। भय, आशंका, आदि","सब छोड़ करके"]],[5113,["आप प्रसन्नचित्त हो करके और इस जगह","आपने जहाँ हाथ रखा है, स्वाधिष्ठान चक्र है,"]],[5118,["और इस चक्र से आप शुद्ध विद्या जानते हैं,","वो विद्या जिससे कि आप"]],[5124,["ब्रह्मशक्ति को किस तरह से चालित करना","चाहिए, उसके बारे में सारा ज्ञान जानते हैं।"]],[5132,["लेकिन इस शुद्ध विद्या के लिए मैं आपको","ज़बरदस्ती नहीं कर सकतीं हूँ; आपको कहना होगा","कि, \"माँ मुझे ये शुद्ध विद्या दीजिए।\""]],[5142,["मैं ज़बरदस्ती नहीं कर सकती हूँ। आपकी स्वतंत्रता","की पूरी इज़्ज़त मुझे करनी है, इसलिए आप","अपनी स्वतंत्रता में ही कहें,"]],[5152,["कि, \"माँ मुझे शुद्ध विद्या दीजिए,\" - छह मर्तबा","कहिए। इस चक्र के छह"]],[5168,["- जैसे कमल की पंखुड़ियाँ होतीं हैं,","उस प्रकार इसकी छह पंखुड़ियाँ हैं,"]],[5174,["\"माँ, मुझे आप कृपया शुद्ध विद्या दीजिए।\""]],[5199,["आँख बंद रखें, आँख न खोलें। कृपया आँख","बिलकुल नहीं खोलना चाहिए। अंतर्योग है,","चित्त अंदर की ओर होना चाहिए।"]],[5210,["अब ये जो राइट हैंड है इसको आप पेट के","ऊपरी हिस्से में फिर से रखें, जहाँ गुरु","का चक्र था मैंने कहा -"]],[5218,["लेफ्ट हैंड साइड में। सब काम लेफ्ट हैंड","साइड में हो रहा है।"]],[5225,["अब अपनी कुण्डलिनी को आप दिलासा दीजिए।","कुण्डलिनी जागृत हो चुकी लेकिन उसे दिलासा","देना होगा जिससे वो ऊपर चढ़े।"]],[5233,["इस जगह आप पूरी आत्मविश्वास के साथ","कहें कि, \"माँ, मैं स्वयं का गुरु हूँ।\""]],[5239,["पूरे विश्वास से कहें, कोई आशंका न रखते हुए,","\"माँ मैं स्वयं का गुरु हूँ।\""]],[5251,["सर में से टोपी आदि निकाल लें, क्योंकि माँ के","सामने क्या टोपी डालने की और फिर","ब्रह्मरंध्र छेदना है ना।"]],[5268,["\"माँ, मैं स्वयं का गुरु हूँ,\" दस बार कहिए।","दस गुरु तत्व हैं हमारे अंदर - दस बार कहिए।"]],[5282,["पूर्ण विश्वास के साथ कहा जाये।"]],[5305,["\"मैं ही स्वयं का गुरु हूँ।\""]],[5322,["अब इस राइट हैंड को हार्ट पे रखें। हार्ट में","आत्मा का स्थान मैंने आपसे कहा है।"]],[5328,["पूर्ण विश्वास के साथ आप कहिए, \"माँ मैं आत्मा हूँ।\"","पूर्ण विश्वास के साथ, \"माँ मैं आत्मा हूँ।\"","बारह मर्तबा।"]],[5368,["हम्म।","साधक: आँखें खोल लें?","श्री माताजी: ना, ना, आँखें बंद रखिए।"]],[5383,["साधक: आप सर आगे बोलिए।","श्री माताजी: हाँ, अच्छा; अब आप थोड़ा शांति करें,","क्योंकि जो सबको देखना है ना,"]],[5391,["सबको साथ ले के चलना है। कुण्डलिनी बैठ जाये","सबकी ह्रदय चक्र तक, फिर आगे चलेंगे, अच्छा।","आप इत्मीनान से रहिए।"]],[5398,["एक दम से भागना नहीं है, आराम से। सबके साथ","चलना है। अच्छा। आँख नहीं खोलिए।"]],[5407,["अब अपना हाथ जो है, अपने कपाल पे रखें -","अपने विशुद्धि चक्र पे रखें।"]],[5415,["विशुद्धि चक्र जो है, ये हमारे गर्दन और हमारा","कन्धा, इसके कोण में लेफ्ट साइड का विशुद्धि चक्र","है - इसपे ज़ोर से पकड़िए।"]],[5427,["पीछे की तरफ हाथ ले जाएँ ज़रा कुछ और।","और ज़ोर से दबा के पकड़िए।"]],[5434,["ये चक्र हमारा तब पकड़ता है, जब हमेशा हम","अपने को दोषी समझते हैं - 'हम पापी हैं,","हम पतित हैं, ये हैं।'"]],[5441,["भाईसाहब, अब आप दूसरों को मत देखिये,","आप खुद पा लीजिए। खुद पा लीजिए।","हाथ इस तरह से रखिए, इधर।"]],[5446,["राइट हैंड इधर रखें। ना, ना, लेफ्ट","नहीं राइट - राइट हैंड।"]],[5466,["इस तरफ से, इनसे भी कहिए, ये भी एक महाशय।","आप सामने से हाथ लीजिए। हाँ, गर्दन से घुमा के,","हाँ सामने से। इनसे भी कहिए।"]],[5478,["हाँ, यहाँ पर अब आप सब ये कहें कि, \"माँ मैं दोषी","नहीं हूँ, मैंने कोई दोष नहीं किया। मैं कोई पतित,","पापी कुछ नहीं हूँ। मैं आत्मा, शुद्ध आत्मा हूँ।\""]],[5495,["साधक: कितनी बार?","श्री माताजी: सोलह मर्तबा। ये श्री कृष्ण का स्थान है।"]],[5507,["आपको पता होना चाहिए कि परमात्मा सिर्फ एक","प्रेम का स्त्रोत नहीं, अनुकम्पा का स्त्रोत नहीं हैं,","सबसे बड़ा तो ये क्षमा का स्त्रोत है।"]],[5523,["और हम ऐसी कोई गलती नहीं कर सकते,","जो परमात्मा अपनी शक्ति में क्षमा करके","उसे पूरी तरह से नष्ट न कर दें।"]],[5531,["इसलिए अपने को दोषी समझना बहुत गलत बात","है, सो पूरी तरह से कहिए कि, \"माँ, मैं बिलकुल","दोषी नहीं हूँ, मैंने कोई गलत काम नहीं किया।"]],[5539,["मैं पतित नहीं हूँ, मैं पापी नहीं हूँ - मैं स्वच्छ आत्मा","हूँ, शुद्ध आत्मा हूँ मैं,\" यहाँ हाथ रख के।","बहुत ज़रूरी है।"]],[5550,["साधक: लेफ्ट हैंड की उँगलियों में तो","जलन मच रही है।"]],[5552,["श्री माताजी: वो तो कुछ गड़बड़ से है, कोई","हर्ज़ नहीं। अभी चली जाएगी थोड़ी देर में।"]],[5558,["चली जाएगी, चली जाएगी। कोई घबड़ाने की","बात नहीं है। अच्छा, सोलह मर्तबा कहिए।"]],[5573,["अब पूर्ण ह्रदय से, चाहे एक ही मर्तबा हो, चाहे दो","ही मर्तबा हो - पर पूर्ण ह्रदय से, आप अपना हाथ","सर के ऊपर"]],[5581,["जहाँ पर कपाल जिसे कहते हैं, उसपर रखिये","और दोनों तरफ से दबाइए - जैसे सर दर्द होता","है तो हम लोग दबाते हैं।"]],[5588,["इस जगह पूर्ण ह्रदय से आप एक बात कहें","- चाहे दो बार, चाहे तीन बार - कि,","\"माँ, मैंने सबको माफ़ कर दिया।\""]],[5599,["पूर्ण ह्रदय से कहें। ना, ना, कपाल, कपाल पे रखें,","सर पे नहीं। कपाल, कपाल किसे कहते हैं आप?","साधक: माथे को।"]],[5607,["श्री माताजी: माथा। नहीं, क्या कहते हैं आप?","साधक: ललाट, ललाट।"]],[5611,["श्री माताजी: ऐ?","साधक: फोरहेड जिसे कहते हैं"]],[5612,["श्री माताजी: फोरहेड पर वो समझ नहीं पा","रहे हैं ना लोग।","साधक: ललाट, ललाट"]],[5616,["श्री माताजी: ललाट। ललाट बहुत सुन्दर है शब्द।","मैंने सोचा ज़रा संस्कृत हो जायेगा इसलिए। हाँ!"]],[5623,["ललाट पे रखिए। \"मैंने सबको माफ़ कर दिया,\"","क्योंकि हम जब किसी को माफ़ नहीं करते हैं"]],[5633,["तो कुछ नहीं करते हैं और करते हैं तो भी कुछ नहीं","करते हैं। लेकिन जब नहीं करते हैं"]],[5637,["तब ज़रूर कोई आदमी जो कि हमें सता रहा है,","परेशान कर रहा है, उसके हाथों खेलते हैं।"]],[5644,["इसलिए कृपया पूर्ण ह्रदय से कहें कि, \"माँ हमने","माफ़ कर दिया।\" ये ना कहें कि, \"मुश्किल है।\""]],[5649,["एकदम कह दें कि, \"माँ, मैंने माफ़ कर दिया।\"","साधक: कितनी बार कहें?"]],[5654,["श्री माताजी: ह्रदय से कहें। मैं ख़ुद जान","जाऊँगी आपने कहा या नहीं कहा।"]],[5658,["कितनी बार की बात नहीं। एक बार कहिए, चाहे","दो बार कहिए, पर पूर्ण ह्रदय से कहें। हाँ !"]],[5666,["अब ये राइट हैंड आप पीछे की तरफ ले जाएँ।","अब एक ही बार कोई दोष अपने पे न लगाते हुए,"]],[5674,["ना पाप गिनते हुए, ना कोई गलतियां गिनते हुए,","एक बार परमात्मा से क्षमा मांग लीजिए"]],[5680,["कि, \"अगर तेरी शान में मैंने कोई, कभी कोई बात","की हो गलती से भी, तो उसे तू क्षमा कर दे।","तुम पिता हो हमारे\""]],[5706,["आँख बंद कर लीजिए, चश्मा उतार लीजिए।","आँख बंद कर लीजिए - यहाँ पकड़िए।"]],[5717,["साधक: ये कितनी बार कहें?","श्री माताजी: बस। अब इस हाथ को आप","तालु के ऊपर रखिए।"]],[5724,["तालु पर तलवा रखिए। तालु आप जानते हैं ना?","जहाँ ब्रह्मरंध्र की स्थिति है और इसको दबाइये।"]],[5732,["और सात मर्तबा घुमाइए। इस जगह भी मैं आपकी","स्वतंत्रता मानती हूँ कि आपको कहना होगा कि,"]],[5738,["\"माँ, मुझे आप पार कराइए। माँ मुझे आप","आत्मसाक्षातकार दीजिए।\" मैं ज़बरदस्ती","नहीं कर सकती।"]],[5745,["[श्री माताजी माइक में फूंकतीं हैं।]"]],[5753,["[श्री माताजी माइक में फूंकतीं हैं।]"]],[5759,["[श्री माताजी माइक में फूंकतीं हैं।]"]],[5765,["[श्री माताजी माइक में फूंकतीं हैं।]"]],[5772,["[श्री माताजी माइक में फूंकतीं हैं।]"]],[5779,["[श्री माताजी माइक में फूंकतीं हैं।]"]],[5785,["[श्री माताजी माइक में फूंकतीं हैं।]"]],[5791,["अब धीरे से हाथ नीचे रखें। दोनों हाथ मेरी ओर","करके आँख धीरे-धीरे खोलिए, बहुत धीरे-धीरे।"]],[5803,["अब लेफ्ट हैंड अपने सर पर उठाके 4 इंच,","5 इंच पे देखिए, कि कोई ठंडी हवा तो"]],[5810,["- लेफ्ट हैंड, लेफ्ट हैंड रखिए, राइट हैंड हमारी","ओर। ऐसे राइट हैंड हमारी ओर करिए।"]],[5816,["यहाँ पर तालु के ऊपर जैसे मैंने, लेफ्ट, लेफ्ट यहाँ","पे। देखिए कोई ठंडी हवा तो नहीं आ रही है?"]],[5828,["टोपी उतार लीजिए बेटे। हाँ - माला-आला","पहने, वो भी उतार लीजिए, अच्छा रहेगा।"]],[5833,["कोई माला अगर पहने हैं तो उतारें, इसीलिए कहा","है जलन आ रही। माला एक मिनिट उतार लीजिए।"]],[5836,["बस एक मिनिट यहाँ सामने रख दीजिए। बस, ठीक","है - अब देखिए अब जलन ख़त्म हो जायेगी। हाँ!"]],[5843,["ज़रा ऊपर, 4-6 इंच ऊपर देखना चाहिए। हाँ!","आप ही अपना सर्टिफिकेट दीजिए, मैं नहीं","देने वाली।"]],[5857,["पा गए आप। अब राइट हैंड हमारी ओर","करें और लेफ्ट हैंड से देखिए।"]],[5867,["खूब गर्मी आ रही है आप लोगों से। राइट हैंड","- लेफ्ट हैंड से देखिए।"]],[5872,["साधक: पहले राइट हैंड (अस्पष्ट)"]],[5873,["श्री माताजी: राइट हैंड मेरी ओर करें, इस तरह से,","ज़रा ऊँचा। हाँ! और लेफ्ट हैंड से देखिए पहले।"]],[5879,["अच्छा, अब जो है लेफ्ट हैंड को मेरी ओर करें","और राइट हैंड से देखिए। (अस्पष्ट)।"]],[5896,["हो गया? आ रही? बहुत सूक्ष्म चीज़ है।","आ गई ना? हाँ, ऊपर।"]],[5903,["साधक: नहीं, कुछ भी नहीं है।","श्री माताजी: आएगी, आएगी, आएगी, आएगी बेटा"]],[5906,["बहुत ज़्यादा घबड़ाहट है आपमें। आएगी, हाथ","बदल के देखिए। नहीं आएगी तो पर करादेंगे पार।","कोई बात नहीं - हाँ।"]],[5916,["कहिए, 'माँ मेरे सर में आइए,' जिसके नहीं आ रही।","कहिए। अभी कुण्डलिनी आपकी माँ है, आ जायेगी।"]],[5925,["हाँ, आ गया?","साधक: नहीं आया।"]],[5929,["श्री माताजी: आ रही? आपके आई? आ रही है।","आ रही है?"]],[5938,["साधक: महसूस नहीं हुआ।","श्री माताजी: ऐं?"]],[5939,["साधक: अभी महसूस नहीं हुआ।","श्री माताजी: महसूस नहीं हुआ - होएगी, होएगी।"]],[5943,["आई बेटा?","साधक: थोड़ी-थोड़ी।"]],[5946,["श्री माताजी: हाँ! ठीक है। अब एक और चीज़","करें। हाथ में महसूस नहीं होता है।"]],[5960,["हाथ को ऊपर करें और गर्दन पीछे करके सवाल","करें कि, \"क्या यही वो ब्रह्मशक्ति है जिसके बारे","में कहा जाता है?\""]],[5968,["\"यही परमात्मा की वो चेतन शक्ति है जिससे","सारे जीवित कार्य होते हैं?\" तीन बार पूछिए।"]],[5983,["अब हाथ नीचे करिए। अब देखिए। आई, हाथ में","लग गई? हाँ! अब पहली मर्तबा महसूस हुई है","चारों तरफ ये शक्ति।"]],[5995,["साधक: अपने को तो कुछ भी नहीं हुआ।","श्री माताजी: होगा बेटे। तुम चिंता बहुत ज़्यादा","करते हो"]],[5999,["चिंता नहीं करो। अभी करते हैं, तुमको","अभी देखते हैं।","साधक: समय लगेगा शायद।"]],[6003,["श्री माताजी: समय नहीं लगेगा। घबड़ाओ नहीं।","जिसको समय लगेगा, उसको लगेगा।"]],[6006,["आपको हो गई?","साधक: ठीक-ठीक कुछ कहना मुश्किल है।"]],[6009,["श्री माताजी: हाँ, अभी, अभी देखिए। जिसको ठीक","ठीक नहीं लग रहा है, उसको अभी देख लेते हैं।"]],[6015,["साधक: क्या महसूस होता है हाथ में?","श्री माताजी: आ रहा है आपको?"]],[6018,["साधक: क्या महसूस होता है हाथ में?","श्री माताजी: ठंडी-ठंडी हवा हाथ में। सर में हुई थी?"]],[6024,["साधक: सर में तो (अस्पष्ट)","श्री माताजी: अभी होगी, ज़रा बैठिए, थोड़ा इत्मीनान","करिए, थोड़ा इत्मीनान।"]],[6030,["इनको हो गया है, इनको हो गया है, इनको हो गया।","अच्छा, जिन-जिन को महसूस हुआ हाथ में","असल में,"]],[6035,["ऊपर हाथ करें, दोनों हाथ, दोनों हाथ। अब देखिए,","इतने लोगों को हो ही गया। अच्छा अब जिन को","नहीं हुआ, कोई घबड़ाने की बात नहीं।"]],[6049,["सब को पार कराना है। आइए, ऊपर आइए, चलिए","एक-एक करके, एक-एक, सबको देखेंगे।"]],[6057,["सहज योगी: इस साइड से, इधर से आइए,","इधर से, इस साइड से आइए।","श्री माताजी: एक, एक करके।"]],[6061,["पैर पे लेना होगा।","सहज योगी: एक-एक करके आइए।"]],[6063,["श्री माताजी: आइए, एक-एक आइए, आइए। आप","पैर पे आइए। आप कौन गुरु के पास गए थे पहले?"]],[6069,["साधक: हम अपने आचार्य श्री राम शर्मा के यहाँ।","श्री माताजी: वहीं पकड़ आ रही है।"]],[6076,["ठीक नहीं हैं, इसलिए। राइट हैंड अपने पेट पे रखो,","इधर। अब ये कहो, \"माँ, मैं ही स्वयं का गुरु हूँ।\"","पूरी तरह से कहो।"]],[6084,["साधक: माँ, मैं ही स्वयं का गुरु हूँ।","श्री माताजी: आँख खोल के।","साधक: माँ, मैं ही स्वयं का गुरु हूँ।"]],[6091,["श्री माताजी: गुरु तत्व की गड़बड़ है, फिर कहिए।","साधक: माँ मैं ही स्वयं का गुरु हूँ।","श्री माताजी: फिर से। आँख खोल के कहिए।"]],[6098,["साधक: माँ, मैं ही स्वयं का गुरु हूँ।","श्री माताजी: हाँ !","साधक: माँ, मैं ही स्वयं का गुरु हूँ। माँ"]],[6104,["श्री माताजी: नहीं हुआ आपका? देखो तो ज़रा,","आज्ञा पे पकड़ है। खुल जायेगा। आज्ञा की ही","पकड़ आ रही है।"]],[6114,["हाँ, आ रही कुछ? आएगा। आओ इधर बैठो।","लड़के देखें। आइये। हाँ, आ जाओ। अब ये","माला-वाला छोड़ो।"]],[6129,["'करका मनका छाड़ि दे मनका मनका फेर' -","आओ। सब कह गए हैं, वो सब सुन-सुन के","हम लोग रटते ही रहते हैं, कुछ करते नहीं हैं।"]],[6138,["हाँ - आज्ञा? आओ। आज्ञा की वाकई में पकड़","है तुमको - किसके पास गए थे?"]],[6145,["साधक: मैं? आज्ञा चक्र के लिए (अस्पष्ट)।","श्री माताजी: रजनीश के पास - हाँ","सहज योगी: तभी!"]],[6152,["श्री माताजी: एँ,","सहज योगी: तभी"]],[6153,["श्री माताजी: किसके?","सहज योगी: रजनीश की काफी किताबें पढ़ीं हैं।"]],[6156,["श्री माताजी: उसी से तो गड़बड़ हो गया है।","चलो मारो उसको गोली। 'रावण मर्दिनी'।"]],[6161,["हाँ, चलो रखो हाथ। ये तो रावण का अवतार है,","समझना चाहिए। जो औरतों की इज़्ज़त पे उठता है,","वो कौन आदमी इंसान हो सकता है?"]],[6170,["राक्षस ही हो सकता है। हाँ! आया, आया? चढ़ गई,","चढ़ गई।"]],[6186,["अब समझ लो बात को। तुम तो कमाल के हो","जो मेरे सामने बैठ गए।"]],[6190,["दूसरे आते - इनसे पूछो। तीन आये थे, वो वहीं","ढर गए - उठ ही नहीं पाए बेचारे।"]],[6197,["अच्छा, तो आपका क्या हाल है? तंदरुस्ती","ठीक नहीं आपकी?","साधक: ठीक है। वैसे बीमारी तो नहीं।"]],[6202,["श्री माताजी: लिवर है आपको। लिवर की शिकायत","है। हम्म, अच्छा, आप बैठिए। इनको ज़रा बताओ","लिवर के लिए क्या करना है।"]],[6207,["आपको नहीं आया?","साधक: हाँ","श्री माताजी : अच्छा, देखिए ऐसे हाथ रखिए।"]],[6210,["क्या है, क्या है?","साधक: अभी नहीं आया।","श्री माताजी: आएगा बेटे, घबड़ाओ नहीं।"]],[6215,["गलत गुरु हो गए थे - कोई नहीं। ज़रा आराम से","- सब लोग आ जाएँ।"]],[6221,["सहज योगी: आपको नहीं आया?","साधक: देख लीजिए ज़रा।"]],[6224,["सहज योगी: अभी नहीं आया?","साधक: (अस्पष्ट)","श्री माताजी: क्या कह रहें हैं?"]],[6230,["आ रहा है? हाँ, ऐसे रखिए। नहीं आया है?"]],[6242,["हैं ना, लिवर का बताओ। इधर आइए।","आपको नहीं आया?"]],[6247,["साधक: एक बार आया था पहले।","श्री माताजी: हाँ?"]],[6249,["साधक: दिल्ली यूनिवर्सिटी में एक बार लेक्चर","सुना था तब तो बहुत आया था।"]],[6251,["श्री माताजी: तब से क्या हो गया?","साधक: कभी आता नहीं, कभी चला जाता है।"]],[6254,["श्री माताजी: तो ध्यान नहीं किये - ध्यान से","ज़माना पड़ता है ना।"]],[6257,["ध्यान है, ध्यान करने पर कैसे होगा। ध्यान करना","पड़ता है। इसको जमाना पड़ता है।"]],[6269,["क्या हुआ, नहीं आया? आएगा, आएगा,","सबको आएगा। हम्म।"]],[6274,["आपके आ गया है। इनके हो गया है।","चलो उठाओ, देखो हाथ। उठाओ इनके।","सिर में आ गया है।"]],[6286,["सहज योगी: बहुत सारी उष्णता।","श्री माताजी: एँ?"]],[6288,["सहज योगी: बहुत गर्मी निकल रही है।","श्री माताजी: बाहर जाने दो। गर्मी है","बहुत इनके। गर्मी तो है ही।"]],[6294,["आपके? आज्ञा पर। आओ - गलत गुरु पकड़","लिए; गली-गली में गुरु बैठे हुए हैं।"]],[6304,["और क्या होएगा? आँख बंद करो। ये हुए","कि नहीं? आप नहीं हुए पार?","साधक: नहीं हुए"]],[6318,["श्री माताजी: अनुभव आपको भी नहीं आया?","साधक: न कुछ भी नहीं।"]],[6320,["श्री माताजी: इनको साक्षात्कार दीजिए, आइए।","बैठ जाइये, ये आपको पार कराएंगे।"]],[6324,["अब ऑस्ट्रेलिया से लोगों को इम्पोर्ट करना","पड़ेगा। इधर मुँह मेरी ओर करिए।"]],[6329,["वो समझायेंगे आपको। अब ये लोग आके आपको","बताएंगे गणपति क्या है। हम तो सब भूल गए;","हम अँगरेज़ हो गए, वो हिंदुस्तानी हो रहे हैं।"]],[6343,["चढ़ी? एकादश, सारा एकादश।"]],[6355,["सहज योगी : कल शाम को भी प्रोग्राम है 6 बजे,","C-49, भगवान दास रोड पे। आप लिख","लीजिए C-49"]],[6365,["श्री माताजी: दिल्ली में","सहज योगी: इधर ही।"]],[6367,["श्री माताजी: यहाँ?","सहज योगी: जयपुर में C-49, भगवान","दास रोड पे।"]],[6371,["साधक: कितने बजे?","सहज योगी: छह बजे।"]],[6373,["साधक: आज शाम को ?","सहज योगी: कल शाम को।"]],[6376,["श्री माताजी: अच्छा, क्या हुआ है?","सहज योगी: जो विशुद्धि है उस वजह से प्रॉब्लम है"]],[6379,["सहज योगी: इस प्रोग्राम में आपको बताया जायेगा","किस तरह से चक्र देखने हैं, किस तरह","उनकी सफाई की जाती है।"]],[6384,["श्री माताजी: सर में आ गई?","सहज योगी: हाँ जी।","श्री माताजी: इनके हिसाब से आ गई।"]],[6386,["साधक: मुझे तो कुछ पता नहीं चला।","श्री माताजी: विशुद्धि चक्र है"]],[6390,["श्री माताजी: वारेन। वो डॉक्टर वारेन के पास जाइये,","आपकी विशुद्धि ठीक कर देंगे। इनकी विशुद्धि।"]],[6396,["साधक: वहाँ जाऊँ?","श्री माताजी: हाँ, वो ठीक कर देंगे। हाँ"]],[6398,["अच्छा - औरों का देखते हैं। आपके?","साधक: प्रोलैप्स पाइल्स का ऑपरेशन कराने में","चक्कर तो नहीं हो गया?"]],[6400,["श्री माताजी: एँ?","साधक: मैंने प्रोलैप्स पाइल्स का ऑपरेशन","कराया था पिछले महीने।"]],[6403,["श्री माताजी: हाँ - तबसे आपकी गई क्या?","साधक: नहीं, कह नहीं सकते। उससे कोई","फर्क तो नहीं पड़ता है?"]],[6408,["श्री माताजी: दिल्ली यूनिवर्सिटी में आ गई थी?","साधक: हाँ जी, बड़ी अच्छी तरह आया था;","बहुत अच्छी वाईब्रेशन्स आईं थीं।"]],[6414,["श्री माताजी: आप बैठो। चलो आओ। दूसरों को देते","होगे - आओ, इनके सर पे हाथ रखो। इधर आओ।","ऐसे हाथ रखो। एक हाथ मेरी ओर। ऐसे।"]],[6450,["हाँ! आया? ठंडक आ रही? हाँ, आ रही?","आपको महसूस हो रहा है, नहीं?"]],[6462,["साधक: शरीर से गर्मी निकल रही है बहुत","ऐसा लग रहा है ।","श्री माताजी: यही तो है।"]],[6465,["साधक: बहुत गर्मी निकल रही है","श्रीमाताजी: गर्मी है"]],[6467,["साधक: पसीना बिल्कुल ....","श्री माताजी: गर्मी बहुत है इनके अंदर। लेफ्ट हैंड,","राइट इसपे रखिए लिवर पे।"]],[6472,["लिवर पे रखिए - ये हाथ मेरी ओर। बस छोड़","दीजिये, आइये। अब तो आप समझ रहे हैं -","महसूस हो रहा है।"]],[6480,["बात ये है कि पार होने के बाद दूसरों का करना","चाहिए, नहीं तो वाइब्रेशन्स ख़तम हो जाते हैं।"]],[6484,["साधक: क्या करें मतलब?"]],[6485,["उसके बाद मेहनत करनी चाहिए, लोगों को देना","चाहिए। जब दीप जला दिया, तो कोई टेबल","के नीचे थोड़ी रखना चाहिए।"]],[6492,["अगर आप दूसरों को साथ दीजियेगा नहीं,","तो विब्रेशन्स क्यों भगवान आपको देंगे?"]],[6495,["साधक: नहीं समझ नहीं आता न दूसरे","का अच्छी तरह।"]],[6497,["श्री माताजी: समझ में आ जायेगा - अब यहाँ","केंद्र खुल रहा है, अच्छा?"]],[6500,["आप यहीं रहते हैं?","साधक: नहीं अब फिर दिल्ली जा रहा हूँ एक महीने","के बाद। एक महीने के लिए यहाँ हूँ।"]],[6504,["श्री माताजी: अच्छा। यहाँ रहिए, अभी तो ये लोग हैं।","अब देखिए? आपके?"]],[6518,["तो ये पार हो गए। खूब अच्छे से। आओ","चलो सिखाएं। आओ खड़े हो जाओ।"]],[6525,["इनको सिखाएं। (मराठी)"]],[6529,["ये बताएँगे। ये देखिए अभी आजकल ये","आये हुए हैं। हाँ, हो गए - नहीं? ऐं?"]],[6535,["सहज योगी: इनको महसूस नहीं हो रहा है","- नाभि और आज्ञा।","श्री माताजी: (मराठी)।"]],[6540,["नाभि, आज्ञा - माथे पे आ गई। कहिए, \"माँ मेरे सर","में आइए\" - बस। माथे पर आज्ञा के बाद।"]],[6552,["आपको? नहीं। (मराठी)"]],[6560,["(मराठी)"]],[6570,["आप भी आइए - आपको ये समझा देंगे","कैसे उठाना है। आइए।"]],[6577,["हाँ, एक पे देख लीजिये आप। हाँ, इनपे देख","लीजिये, हाँ! आप इनपे देखिए वो कर रहे हैं।"]],[6584,["आओ, पाटनकर - (मराठी)"]],[6596,["हम्म, क्या हाल? गर्मी निकल रही काफी","- बहुत गर्मी है।","साधक: इसका कोई विशेष अनुभव है?"]],[6603,["श्री माताजी: हाँ नहीं, लेकिन गर्मी बहुत है ना आपके","अंदर - ऐसे हाथ रखिए। राइट हैंड मेरी ओर।","क्या काम करते हैं आप?"]],[6609,["हैं?","साधक: ऑफिस में"]],[6610,["श्री माताजी: क्या काम?","साधक: लेखनाचार्य, अकाउंटेंट"]],[6614,["श्री माताजी: अकाउंटेंट - रखिए हाथ।","क्या इनका क्या है?"]],[6619,["सहज योगी: वोयड (भवसागर) पे धड़कन हो","रही है इनके"]],[6621,["श्री माताजी: वॉइड पे। गुरु कौन हैं? कोई न कोई","होंगे। किसी के यहाँ गए होंगे? किसी के भाषण","में नहीं गए, कभी नहीं?"]],[6629,["साधक: भाषण में तो जाते रहते हैं।","श्री माताजी: आ","साधक: भाषण में तो जाते रहते हैं।"]],[6631,["श्री माताजी: वो ही तो बात है। अच्छा अब","इसको गुरु के चक्र पे राइट हैंड रखें।"]],[6638,["और कहिए कि, \"मैं ही अपना गुरु हूँ।\" हो गया","ठीक? चलने लग गया हाथ। अब दूसरों","को दीजिये।"]],[6646,["साधक: मुझे नहीं आया।","श्री माताजी: नहीं? हो जायेगा आपको।","आपको? नहीं?"]],[6661,["सहज योगी: जिनका हो गया है वो नीचे","उतरें और लोगों को आने दें।"]],[6663,["श्री माताजी: आप रखिए इनके सिर पे एक हाथ","- एक हाथ मेरी ओर। नीचे से उठाइए","कुण्डलिनी - हाँ!"]],[6671,["सहज योगी: जो लोग जा रहे हैं, पहले फोटोग्राफ ले","जाइएगा और किस तरह फोटो पर काम करना है,","वो अभी बता देंगे आपको।"]],[6683,["श्री माताजी: आँख, आँख खुली रखें।","आँख खुली रखिए। इनको मिल गया?"]],[6690,["सहज योगी: फोटो के सामने कैंडल रखके और","हाथ जिस तरह आज रखे हैं उसी तरह रखके,","वाईब्रेशन्स आप महसूस कर सकते हैं"]],[6699,["और जिन चक्रों में आपको गर्मी आती है,","उन चक्रों में किस तरह वाईब्रेशन्स देनी हैं,"]],[6704,["ये कल 6 बजे बताया जायेगा, C-49 भगवानदास","रोड पर।"]],[6708,["श्री माताजी: गर्मी बहुत है, बहुत गर्मी है","आपके अंदर।"]],[6711,["फोटोग्राफ और किताबें हैं यहाँ पर,","वो आप ले के जाइए।"]],[6713,["श्री माताजी: हैं?","साधक: सिंपल और रिस्ट्रिक्टेड","डाइट वगैराह बहुत ही अपना"]],[6717,["(अस्पष्ट) के रखता हूँ। काफी अनुशासित","तरीका जीने का है मेरा।"]],[6723,["श्री माताजी: बहुत ज़्यादा है उसका। इतना","अपने शरीर के साथ खेल नहीं करना चाहिए।","साधक: हाँ ये हो सकता है।"]],[6727,["बहुत ज़्यादती आपने कर ली। अपने साथ बहुत","ज़्यादती कर ली, इसीलिए राइट साइड","पकड़ा हुआ है।"]],[6731,["साधक: हाँ ये तो हो सकता है। बाकी कोई गलत","कदम मैं कभी नहीं लेता।"]],[6737,["श्री माताजी: नहीं, नहीं, लेकिन ये आप अपने साथ","बहुत ज़्यादती करते हैं और बहुत ज़्यादा सोचते हैं।"]],[6741,["साधक: हाँ ये तो है - थिंकिंग (सोचना) बहुत","ज़्यादा है।"]],[6748,["साधक: हाँ, अब थोड़ा","श्री माताजी: शुरू हुआ। बेटर"]],[6759,["क्या इनका हो रहा है?","साधक: इन्हें प्राप्त हो गया है माँ, लेकिन","यह फिर से पीछे गिर रही है।"]],[6764,["श्री माताजी: उसे बाँध दो। यह सभी प्रकार के","गुरुओं के पास गए हैं। इनको देखिए - ये दोनों","होने चाहिए - जल्दी हो जाएंगे।"]],[6771,["डॉक्टर साहब, इनको देखिए। ये, दो मिनिट में","ये लोग पार हो जाएंगे। ये भी हो जाएंगे।"]],[6778,["होना चाहिए। अब? कुछ ठंडक तो शुरू हुई।","साधक: थोड़ा सा"]],[6782,["श्री माताजी: अच्छा आप बैठ जाइए इधर।","थोड़ी देर ऐसे ही बैठो जैसे हमने कहा।","हाथ ऐसे - नीचे उधर सरक के।"]],[6788,["आप आ जाइए। नहीं हो रहा है आपके?","क्या बात? देखते हैं।"]],[6805,["आप क्या करते हैं?","साधक: डॉक्टर हूँ, आँखों का।"]],[6808,["श्री माताजी: हैं?","साधक: आँखों का डॉक्टर हूँ।"]],[6810,["श्री माताजी: आँखों का, आई स्पेशलिस्ट।","साधक: पहले ऑस्ट्रेलिया था। पांच साल तक","मेलबोर्न था, उसके बाद (अस्पष्ट) प्रैक्टिस शुरू की।"]],[6816,["श्री माताजी: वहाँ से अब आप यहाँ आये!","अच्छा! हाँ। वॉरेन, मेलबर्न से एक डॉक्टर हैं।","आगे आइए आगे।"]],[6833,["बहुत पसीना आ रहा है। क्या हुआ?","साधक: कुछ नहीं","श्री माताजी: क्या कह रहे हैं? नहीं हो रहा है?"]],[6845,["छोड़ दिया उन्होंने? क्या कह रहे हैं? होएगा। बैठो।","निश्चिन्त हो जाओ। ज़रा निश्चिंती से बैठो,","निश्चिंती से बैठो।"]],[6860,["अब बोलो?"]]]);
